INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$f44d3b4f-b5fd-5d50-9e4a-8fc88238032c$ml$::uuid, $ml$ai$ml$, 1, 1, $ml${"id": "ai-d1-c1", "title": "One point for a right answer", "lessonTitle": "Three ways a machine learns", "slot": 1, "type": "apply", "brief": {"headline": "DeepSeek's R1 learned to reason largely by trial and error: a reward of 1 for a correct answer, 0 otherwise. Nature published the work in September 2025, with R1's training put at $294,000.", "kicker": "Apply day 1: which way of learning taught R1 to reason?", "fullText": "DeepSeek built R1 on its V3 Base model, which had been trained with conventional methods on web data. The reasoning came next, through reinforcement learning. The model got a reward of 1 for a correct answer and 0 otherwise. Math answers were checked against the right answer, and code against test cases. It was not trained on thousands of human-labeled worked solutions.\n\nThe peer-reviewed paper appeared in Nature on September 17, 2025. Supplementary material put R1's training at the equivalent of $294,000, on top of about $6 million for the base model. R1 has been downloaded 10.9 million times on Hugging Face.\n\nCritics note that the base model's conventional start may explain part of the result. Still, the reasoning stage learned from rewards, not from answers written by people.", "sources": [{"url": "https://www.scientificamerican.com/article/secrets-of-chinese-ai-model-deepseek-revealed-in-landmark-paper", "label": "Scientific American, Secrets of DeepSeek AI model revealed, Sep 2025"}, {"url": "https://sciencenews.org/article/ai-model-deepseek-answers-training", "label": "Science News, A look under the hood of DeepSeek's AI models, Dec 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about how R1 learned to reason. Tap it.", "statements": ["It got a reward of 1 for a correct answer, 0 otherwise.", "It learned from thousands of human-labeled worked solutions.", "Its code answers were checked against test cases."], "fakeIndex": 1, "explanation": "R1 was rewarded only for outcomes. No one showed it step-by-step human solutions, which is what makes this reinforcement learning."}, "numbers": {"kind": "numberSense", "prompt": "R1's reasoning stage cost $294,000; its base model about $6 million. How many times more did the base cost?", "min": 0, "max": 60, "value": 20, "unit": "x", "explanation": "About 20 times. The cheap headline figure sits on top of a base model that cost far more."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a machine learning role. They ask what R1's reasoning stage learned from.", "prompt": "Which answer shows you know how it works?", "options": ["Worked solutions labeled by human experts", "Patterns it found in unlabeled text alone", "Rewards for answers a program could check"], "correctIndex": 2, "consequences": ["That would be supervised learning, which this stage avoided.", "Pattern-finding describes unsupervised learning, not this stage.", "Right: 1 for a correct answer, 0 otherwise, checked automatically."], "explanation": "Naming what a model learns from, here a checkable reward, shows you know what it needs to work."}, "proReasoning": "Strong candidates name the raw material: labels, patterns or rewards. For R1, the reward was an automatic check of each answer.", "commonMistake": "Saying it \"taught itself\" without naming the reward that did the teaching.", "mentalModel": "Name what the model learns from."}, "invest": {"call": {"kind": "theCall", "situation": "Headlines say DeepSeek trained R1 for $294,000. You're judging what that means for AI costs.", "prompt": "What should you keep in mind?", "options": ["It leaves out the base model, so the total was higher", "Frontier AI now costs under $300,000 to build in total", "Reinforcement learning means no chips were needed at all"], "correctIndex": 0, "consequences": ["The base model alone cost about $6 million.", "The $294,000 covers only the reasoning stage on top.", "R1 still trained on NVIDIA chips; rewards replace labels, not compute."], "explanation": "A cost figure is only useful once you know what it covers. This one leaves out the base model."}, "proReasoning": "Investors ask what a training cost includes before comparing it. A stage cost and a full cost are different numbers.", "commonMistake": "Comparing one stage of training with the full cost of a rival model.", "mentalModel": "Ask what the cost figure covers."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to train a model to fill in tax forms, using rewards the way R1 did.", "prompt": "What must you have before you start?", "options": ["A model bigger than anyone else has", "A way to check each answer automatically", "Millions of worked examples written by people"], "correctIndex": 1, "consequences": ["Size was not the point; the checkable reward was.", "Without an automatic check, there is no reward to learn from.", "Worked examples are what this approach tries to avoid."], "explanation": "Reinforcement learning needs a reward you can measure. R1 worked because math and code answers can be checked."}, "proReasoning": "Founders check the raw material first. Rewards need an answer a program can grade; labels need people to write them.", "commonMistake": "Copying the method without asking whether your task can be graded automatically.", "mentalModel": "No checkable answer, no reward."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says DeepSeek built an AI that taught itself to reason with no help at all.", "prompt": "What's the fairer version?", "options": ["Yes, it started from nothing at all, like a newborn", "No, people wrote out every single step it learned", "Rewards trained its reasoning, on top of a trained base"], "correctIndex": 2, "consequences": ["It started from V3 Base, which was already trained on web data.", "No one wrote its steps; it was rewarded only for correct answers.", "The reasoning came from rewards, on top of a conventionally trained base."], "explanation": "The reward did the teaching for the reasoning stage. The base model underneath was trained the usual way."}, "proReasoning": "When you hear \"taught itself\", ask what rewarded it and what it started from. Both parts matter.", "commonMistake": "Thinking reinforcement learning means starting from zero.", "mentalModel": "Ask what rewarded it, and where it started."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$72ebbc4f-e549-5dfd-babd-ac065107ede9$ml$::uuid, $ml$ai$ml$, 1, 2, $ml${"id": "ai-d1-c2", "title": "From human games to self-play", "lessonTitle": "Three ways a machine learns", "slot": 2, "type": "connect", "brief": {"headline": "Earlier versions of AlphaGo first learned from thousands of human games. AlphaGo Zero learned only by playing itself, and after 40 days it had passed every earlier version.", "kicker": "Connect two day 1 ideas: learning from answers, then from rewards.", "fullText": "Day 1 covered three ways a machine learns. AlphaGo's history shows two of them.\n\nEarlier versions of AlphaGo first trained on thousands of games played by human amateurs and professionals. Each human move was an answer to learn from, which is supervised learning.\n\nAlphaGo Zero started from random play with no human games at all. It played millions of games against itself and learned from who won. After three days it beat the version that had defeated Lee Sedol, 100 games to 0. After 40 days it had passed AlphaGo Master too.\n\nChatbots often use both teachers. InstructGPT first learned from human demonstrations, then from people ranking its answers as a reward.", "sources": [{"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}, {"url": "https://openai.com/index/instruction-following/", "label": "OpenAI, InstructGPT"}, {"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}]}, "evidence": {"kind": "buildChain", "prompt": "Put AlphaGo Zero's learning cycle in order.", "steps": ["Start from random play, with no human games", "Play games against itself", "Learn to predict good moves and the winner", "Combine the updated network with search", "Play again as a stronger version"], "explanation": "Each cycle of self-play makes a stronger player. No human move is ever the answer key."}, "numbers": {"kind": "numberSense", "prompt": "After how many days of self-play had AlphaGo Zero passed AlphaGo Master?", "min": 0, "max": 100, "value": 40, "unit": "days", "explanation": "About 40 days, starting from random play. Three days were enough to beat the version that beat Lee Sedol."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chatbot team. They ask why it uses both human demonstrations and human rankings.", "prompt": "What's the best answer?", "options": ["Demos show good answers; rankings reward better ones", "Rankings are cheaper, so demos are being dropped", "Both are labels, just collected twice for safety"], "correctIndex": 0, "consequences": ["Right: one step is supervised, the next is reinforcement.", "InstructGPT used both steps, in that order.", "Rankings become a reward, which is a different way of learning."], "explanation": "Demonstrations are answers to copy. Rankings become a reward. InstructGPT chained the two."}, "proReasoning": "Explain each training step by what it learns from. Demonstrations are labels; rankings are a reward.", "commonMistake": "Calling all human input \"labels\" and missing the reward step.", "mentalModel": "One step copies, the next is scored."}, "invest": {"call": {"kind": "theCall", "situation": "One game AI learns from records of human play. Another learns only by playing itself.", "prompt": "Which one depends less on human-made data?", "options": ["Both depend on human data equally", "The one that learns by playing itself", "The one trained on human game records"], "correctIndex": 1, "consequences": ["Self-play needs no human games, as AlphaGo Zero showed.", "Self-play makes its own data; the cost shifts to compute.", "Human records must be collected, so people make that data."], "explanation": "Human data is part of the cost of supervised learning. Self-play swaps that cost for compute."}, "proReasoning": "Investors ask who supplies a model's data and at what price. Self-play moves the bill from people to machines.", "commonMistake": "Assuming every AI model needs a large supply of human-made data.", "mentalModel": "Follow who makes the training data."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a support chatbot. You have 2,000 strong answers written by your best agents.", "prompt": "How do you use them?", "options": ["Ignore them and rely on rankings alone", "Use them only to group tickets by topic", "Train on them first, then add ranked feedback"], "correctIndex": 2, "consequences": ["Throwing away good demonstrations wastes the easiest step.", "Grouping by topic uses none of the answers they wrote.", "That is the InstructGPT recipe: copy good answers, then learn from rankings."], "explanation": "Good examples are labeled data. Use them for the supervised step, then improve with rankings."}, "proReasoning": "Founders use the data they already have for the step it suits. Written answers suit supervised learning.", "commonMistake": "Jumping to the fancy step and skipping the data already in hand.", "mentalModel": "Match each dataset to its step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an AI that never saw a human game beat one trained on human games.", "prompt": "What's the best explanation?", "options": ["Self-play let it find moves no human taught it", "It secretly studied far more human games", "Engineers typed in better Go strategies by hand"], "correctIndex": 0, "consequences": ["Learning from wins and losses, it was not limited to human moves.", "AlphaGo Zero used no human games at all.", "No strategies were coded in; it learned by playing itself."], "explanation": "Learning from human moves caps you near human play. Learning from results lets the model go past it."}, "proReasoning": "Copying a teacher gets you close to the teacher. Learning from results can take you past them.", "commonMistake": "Assuming more human data is always the better teacher.", "mentalModel": "Rewards can teach past the teacher."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$75a20523-f251-52d1-8674-f5ed872ed050$ml$::uuid, $ml$ai$ml$, 1, 3, $ml${"id": "ai-d1-c3", "title": "An opponent for a new game", "lessonTitle": "Three ways a machine learns", "slot": 3, "type": "decide", "brief": {"headline": "You run a small studio launching a new board game. Nobody has played it yet, so there are no records of human games. You need a strong AI opponent at launch.", "kicker": "Decide which way of learning fits a game with no human data.", "fullText": "Supervised learning needs examples with the right answer attached. Unsupervised learning finds patterns with no answers. Reinforcement learning tries things and learns from rewards or penalties.\n\nYour game has clear rules and a clear winner, but no recorded human games. AlphaGo Zero faced the same situation by choice: it started from random play and learned from self-play alone. After three days it beat the AlphaGo that had beaten Lee Sedol, 100 games to 0, running on 4 TPUs where that earlier version used 48.", "sources": [{"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}, {"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}]}, "evidence": {"kind": "sortSignal", "prompt": "What does each way of learning need for your game?", "buckets": ["Supervised", "Reinforcement"], "items": [{"text": "Thousands of recorded human games", "bucket": 0}, {"text": "The right move marked for each position", "bucket": 0}, {"text": "A clear win or loss at the end", "bucket": 1}, {"text": "A fast way to play huge numbers of games", "bucket": 1}], "explanation": "Supervised learning needs answers you do not have. Reinforcement needs a measurable result, which your game gives."}, "numbers": {"kind": "numberSense", "prompt": "The AlphaGo that beat Lee Sedol ran on 48 TPUs. How many did AlphaGo Zero run on?", "min": 0, "max": 24, "value": 4, "unit": "TPUs", "explanation": "Four. Self-play beat the older version 100 to 0 on far less hardware."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The studio offers you one of two roles for the AI project: labeling played games, or building the game simulator.", "prompt": "Which role matters more to the self-play plan?", "options": ["Writing rules for each opening move", "Building the fast game simulator", "Labeling games that humans played"], "correctIndex": 1, "consequences": ["Hand-written openings are what self-play replaces.", "Self-play runs on the simulator, so its speed sets the pace.", "There are no human games to label yet."], "explanation": "In reinforcement learning, the environment that produces rewards is the core asset."}, "proReasoning": "Pick the role that supplies what the method needs. For self-play, that is a fast, correct game environment.", "commonMistake": "Choosing the data-labeling role when the plan needs no labels.", "mentalModel": "Work where the method gets its raw material."}, "invest": {"call": {"kind": "theCall", "situation": "Two game AI startups pitch you. One will pay experts to play 50,000 games; the other will use self-play.", "prompt": "Which cost grows more slowly as they scale?", "options": ["Paid expert games, since humans teach best", "Both scale the same way per game", "Self-play, which needs compute, not people"], "correctIndex": 2, "consequences": ["Experts are slow and paid per game, and Zero beat human-trained play.", "A human game costs far more time than a simulated one.", "Machines generate the games, and AlphaGo Zero did it on 4 TPUs."], "explanation": "Human data is a cost that grows with every example. Self-play turns that cost into compute."}, "proReasoning": "Investors compare what each extra example costs. Human-made data scales with people; self-play scales with machines.", "commonMistake": "Assuming human-made data is always worth its cost.", "mentalModel": "Price each extra example."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The game has a clear winner and no human records, and launch is in six months.", "prompt": "How do you train the opponent?", "options": ["Self-play, rewarded for winning games", "Wait years to collect human games first", "Group positions with no goal at all"], "correctIndex": 0, "consequences": ["A clear win or loss is exactly the reward self-play needs.", "You would launch with no opponent at all.", "Pattern-finding without a goal will not learn to win."], "explanation": "A measurable reward plus a simulator is all reinforcement learning needs. Your game has both."}, "proReasoning": "Founders choose the method by the data they can get. With rules and a winner, self-play needs nothing else.", "commonMistake": "Waiting for data the method does not need.", "mentalModel": "A clear winner makes a clear reward."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an AI could get good at a game that no person has ever played.", "prompt": "What's the answer?", "options": ["Someone programs in every good move", "It plays itself and learns from who wins", "It copies moves from games that look similar"], "correctIndex": 1, "consequences": ["Nobody knows the good moves yet; the AI finds them.", "That is reinforcement learning, the way AlphaGo Zero learned Go.", "Copying needs examples, and this game has none."], "explanation": "Rewards from winning and losing are enough to learn from, with no examples needed."}, "proReasoning": "A clear goal can stand in for a teacher. The AI tries, scores, and adjusts.", "commonMistake": "Thinking an AI always needs human examples to learn.", "mentalModel": "A score can be the teacher."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f54ce230-0132-5bcc-ac9e-349dc89113bc$ml$::uuid, $ml$ai$ml$, 2, 1, $ml${"id": "ai-d2-c1", "title": "Same model, 80% cheaper", "lessonTitle": "Where the money in AI goes", "slot": 1, "type": "apply", "brief": {"headline": "On June 10, 2025, OpenAI cut the price of its o3 reasoning model by 80%. Output fell from $40 to $8 per million tokens. It was the same model, served more cheaply.", "kicker": "Apply day 2: the price of each answer keeps falling.", "fullText": "In mid-2025, o3 was OpenAI's most powerful reasoning model. On June 10, Sam Altman announced the price was down 80%: $2 per million input tokens instead of $10, and $8 per million output tokens instead of $40. It was the very same model, and an OpenAI staff member credited the engineers optimizing inference.\n\nRivals were close. Google's Gemini 2.5 Pro cost $1.25 to $2.50 per million input tokens and $10 to $15 for output. Anthropic's Claude Opus 4 cost $15 in and $75 out.\n\nThis is the day 2 pattern. Each answer keeps getting cheaper, which brings more users. Every answer still runs on chips in a data center, and that is where the money flows.", "sources": [{"url": "https://venturebeat.com/ai/openai-announces-80-price-drop-for-o3-its-most-powerful-reasoning-model", "label": "VentureBeat, OpenAI announces 80% price drop for o3, Jun 2025"}, {"url": "https://simonwillison.net/2025/Jun/10/o3-price-drop/", "label": "Simon Willison, o3 price drop, Jun 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "o3's output price fell from $40 to $8 per million tokens, for the very same model. What changed?", "options": ["OpenAI swapped in a smaller model", "The chips started running for free", "How efficiently OpenAI served it"], "correctIndex": 2, "explanation": "The model stayed the same. OpenAI credited the engineers optimizing inference, the cost of serving each answer."}, "numbers": {"kind": "numberSense", "prompt": "You spent $400 a month on o3 output before the cut. What does the same usage cost after an 80% cut?", "min": 0, "max": 400, "value": 80, "unit": "dollars", "explanation": "$80. An 80% cut leaves a fifth of the bill, so the same work now costs one dollar in five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a product role at an app built on o3, the week of the cut. They ask what it changes.", "prompt": "What's your answer?", "options": ["Features too costly last month may now pay off", "Nothing, since prices will go back up soon", "The model got worse, so we should switch"], "correctIndex": 0, "consequences": ["At a fifth of the cost, more features clear the bar.", "The trend in AI prices has been steadily down.", "It was the same model, only cheaper to serve."], "explanation": "A product team watches its cost per answer. When that cost drops 80%, the roadmap changes."}, "proReasoning": "Link a price change to what the team can now build. Knowing where a team's costs sit is half the answer.", "commonMistake": "Treating a price cut as a sign the product got worse.", "mentalModel": "Cheaper answers widen the roadmap."}, "invest": {"call": {"kind": "theCall", "situation": "A model maker cuts prices 80%. Revenue per answer drops to a fifth of what it was.", "prompt": "What decides whether the cut grows revenue?", "options": ["Nothing, since cheaper is always better", "Whether usage grows more than five times", "Whether rivals notice the new price"], "correctIndex": 1, "consequences": ["Cheaper helps users; it can still shrink revenue.", "At a fifth of the price, usage must grow over 5x just to keep revenue.", "Rivals' reaction matters, but usage pays the bills."], "explanation": "Falling prices cut both ways. Watch usage growth against the size of the cut."}, "proReasoning": "Investors compare the price cut with the usage it brings. An 80% cut needs more than 5 times the usage to grow revenue.", "commonMistake": "Cheering a price cut without checking the volume needed to pay for it.", "mentalModel": "Watch usage against price."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI feature lost money on o3 at $40 per million output tokens. The price is now $8.", "prompt": "What do you do?", "options": ["Drop the feature, since it lost money", "Wait for prices to be cut again", "Redo your unit economics at $8"], "correctIndex": 2, "consequences": ["You may be dropping a feature that now pays.", "Waiting gives rivals the head start.", "A feature that lost money at $40 may profit at $8."], "explanation": "Today's costs are not tomorrow's. When the input price moves, redo the math before deciding."}, "proReasoning": "Founders recheck the numbers every time model prices move. A dead feature can come back to life.", "commonMistake": "Treating last quarter's costs as permanent.", "mentalModel": "Redo the math when prices move."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the same AI model can suddenly cost 80% less.", "prompt": "What's the best explanation?", "options": ["Engineers made it cheaper to run", "OpenAI made the model smaller and worse", "A government pays the difference"], "correctIndex": 0, "consequences": ["OpenAI credited work on serving it more efficiently.", "It was the very same model.", "No subsidy was involved; the serving got cheaper."], "explanation": "Every answer costs compute. Serve it more efficiently and the price can fall without changing the model."}, "proReasoning": "Running a model is a cost of its own, apart from building it. Better serving can cut prices fast.", "commonMistake": "Assuming a cheaper model must be a worse one.", "mentalModel": "Running cost sets the price."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$b91bb62b-9b2c-5c5e-9336-f5cf08a72343$ml$::uuid, $ml$ai$ml$, 2, 2, $ml${"id": "ai-d2-c2", "title": "Two bills behind a chatbot", "lessonTitle": "Where the money in AI goes", "slot": 2, "type": "connect", "brief": {"headline": "GPT-4's training compute cost an estimated $78 million. Chatbots like InstructGPT also learned from people who wrote demonstrations and ranked answers. Both bills come before anyone uses the model.", "kicker": "Connect day 1 and day 2: chatbots pay for compute and for people.", "fullText": "On day 1 you saw how chatbots learn. InstructGPT learned from human demonstrations, then from people ranking its answers as a reward. People make that data, and people get paid.\n\nOn day 2 you followed the money. Training compute for GPT-4 cost an estimated $78 million, and Gemini Ultra an estimated $191 million. Most of it flows down to cloud compute and chips.\n\nPut together, a chatbot has two big training bills: machines and human feedback. Only once it is trained does the cheap part begin, as the price of each answer keeps falling.", "sources": [{"url": "https://openai.com/index/instruction-following/", "label": "OpenAI, InstructGPT"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each cost part of the compute bill or the human data bill?", "buckets": ["Compute", "Human data"], "items": [{"text": "GPU time to train GPT-4", "bucket": 0}, {"text": "Cloud servers answering users", "bucket": 0}, {"text": "Chips bought from a chipmaker", "bucket": 0}, {"text": "People writing example answers", "bucket": 1}, {"text": "People ranking the model's answers", "bucket": 1}], "explanation": "Machines run the training and the answers. People write and rank the examples the model learns from."}, "numbers": {"kind": "numberSense", "prompt": "Gemini Ultra's training compute cost about $191 million, GPT-4's about $78 million. How many million dollars more?", "min": 0, "max": 300, "value": 113, "unit": "M", "explanation": "About $113 million more, for compute alone. Human feedback is a separate bill."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chatbot lab. They ask where training money goes.", "prompt": "Which answer is most complete?", "options": ["Only labelers, since compute has become cheap", "Mostly compute, plus paid human feedback", "Only chips, since human feedback costs nothing"], "correctIndex": 1, "consequences": ["GPT-4 alone used an estimated $78 million of compute.", "Right: compute is the biggest bill, and human data is a real cost.", "People who write and rank answers are paid for that work."], "explanation": "Chatbots pay twice in training: for machines and for human-made data."}, "proReasoning": "Name both cost lines and which is bigger. It shows you know what a training run actually buys.", "commonMistake": "Forgetting the human data bill because compute is so large.", "mentalModel": "Machines and people both cost money."}, "invest": {"call": {"kind": "theCall", "situation": "A chatbot maker says answer prices fell 280-fold, so its costs are disappearing.", "prompt": "What's missing from that claim?", "options": ["Nothing, since answers drive all the costs", "Answer prices have risen since 2022", "Training compute and human data still cost money"], "correctIndex": 2, "consequences": ["Training runs cost tens of millions before any answer is sold.", "GPT-3.5-level answers fell from $20 to $0.07 per million tokens.", "Cheaper answers do not shrink the bill to train the next model."], "explanation": "Serving costs fall fast. Training compute and human feedback are separate bills that come first."}, "proReasoning": "Investors split costs into training and serving. A falling price per answer says little about the next training run.", "commonMistake": "Reading cheaper answers as cheaper models overall.", "mentalModel": "Training and serving are separate bills."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are drafting the training budget for a chatbot tuned to your industry.", "prompt": "What must the budget cover?", "options": ["Compute and paid human feedback", "Compute only, since feedback comes free", "Human feedback only, since compute is cheap"], "correctIndex": 0, "consequences": ["Both are real costs of a trained chatbot.", "Someone has to write and rank the answers, and they are paid.", "Training compute still costs serious money."], "explanation": "Feedback-trained models need data made by people, and they need compute to learn from it."}, "proReasoning": "Founders budget for the people who make training data, not just the GPUs. Both sit in the cost of the model.", "commonMistake": "Leaving human data out of the budget.", "mentalModel": "Budget for machines and for people."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why chatbot makers pay people when the AI does the work.", "prompt": "What's the answer?", "options": ["People check every answer before you see it", "People write and rank the answers it learns from", "People secretly type the replies you get"], "correctIndex": 1, "consequences": ["Answers reach you directly; people helped train the model earlier.", "That human feedback is part of how chatbots are trained.", "The replies come from the model itself."], "explanation": "Human demonstrations and rankings are training data. Making them is paid work."}, "proReasoning": "Behind a chatbot are people who taught it, long before you typed a word. That work is part of its cost.", "commonMistake": "Thinking an AI model trains itself with no human input.", "mentalModel": "People teach the model before it talks."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$21933472-0f3e-5401-9f3a-1687b6af0889$ml$::uuid, $ml$ai$ml$, 2, 3, $ml${"id": "ai-d2-c3", "title": "Pricing a free tier", "lessonTitle": "Where the money in AI goes", "slot": 3, "type": "decide", "brief": {"headline": "You run a small AI writing app and want a free tier. GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months.", "kicker": "Decide what falling answer prices let you offer.", "fullText": "Money in AI flows down the stack. Users pay apps, apps pay model makers, model makers pay for cloud compute, and the cloud buys chips. NVIDIA's data center business alone brought in $193.7 billion in fiscal 2026.\n\nMeanwhile the price of each answer keeps falling. Stanford's AI Index found that GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months, a 280-fold drop. A free tier that would have been ruinous in 2022 can cost very little today.", "sources": [{"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["GPT-3.5-level answers fell from $20 to $0.07 per million tokens.", "The fall took about 18 months.", "Cheaper answers left chipmakers earning almost nothing."], "fakeIndex": 2, "explanation": "NVIDIA's data centers brought in $193.7 billion in fiscal 2026. Cheaper answers brought more use, and the money still flows to compute."}, "numbers": {"kind": "numberSense", "prompt": "A free user sends 1 million tokens a month. At $0.07 per million, what do they cost you a year, in cents?", "min": 0, "max": 200, "value": 84, "unit": "cents", "explanation": "12 months at 7 cents is 84 cents a year. At 2022 prices of $20 per million, it would have been $240."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to lead product at the app. The founder asks whether a free tier makes sense.", "prompt": "What's your best answer?", "options": ["No, AI answers are too expensive to give away", "Yes, and make every feature free forever", "Yes, if cost per free user stays tiny"], "correctIndex": 2, "consequences": ["That was true in 2022, not after a 280-fold drop.", "Some features may still cost real money to run.", "At cents a year per user, a free tier can pay for itself in sign-ups."], "explanation": "Answer the question with the cost per user. Falling prices are why free tiers work now."}, "proReasoning": "Back a product call with unit costs. \"About 84 cents a year per free user\" beats a gut feeling.", "commonMistake": "Judging AI costs by 2022 prices.", "mentalModel": "Price the free user first."}, "invest": {"call": {"kind": "theCall", "situation": "The app launches a free tier and users triple, but revenue per user falls.", "prompt": "How do you read that?", "options": ["Track how many free users turn paid", "Sell, since revenue per user fell", "Ignore it, since users tripled"], "correctIndex": 0, "consequences": ["Cheap free users pay off only if some upgrade.", "Revenue per user falls by design when free users join.", "Users alone do not pay the bills."], "explanation": "Falling prices bring more users but shrink what each earns. Conversion decides the outcome."}, "proReasoning": "Investors watch usage growth against what each user earns. A free tier is a bet on conversion.", "commonMistake": "Reading a drop in revenue per user as failure, or growth in users as success.", "mentalModel": "Free users pay off when some convert."}, "build_startup": {"call": {"kind": "theCall", "situation": "A premium feature needs a frontier model and is too costly to run for every user today.", "prompt": "What do you do?", "options": ["Give it to everyone free and absorb the cost", "Charge for it now and plan for costs to fall", "Drop it, since it will always cost too much"], "correctIndex": 1, "consequences": ["Free use at today's frontier prices can sink a small app.", "Prices have dropped 280-fold before, so plan for cheaper.", "Costs that look fixed today have fallen fast before."], "explanation": "Today's costs are not tomorrow's. Charge for it now, and widen access as prices drop."}, "proReasoning": "Founders plan for falling AI prices without betting the company on them. Charge now, widen later.", "commonMistake": "Killing a feature because of what it costs this year.", "mentalModel": "Charge now, widen as costs fall."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many AI apps let you use them for free.", "prompt": "What's the main reason?", "options": ["The apps are all run by charities for free", "AI answers cost nothing at all to produce", "Answers now cost a sliver of 2022 prices"], "correctIndex": 2, "consequences": ["Most are businesses hoping some users pay.", "Every answer still runs on chips that cost money.", "A 280-fold drop makes free users cheap to serve."], "explanation": "Answers got so cheap that serving free users costs little, and some of them will pay later."}, "proReasoning": "Free tiers follow costs. When an answer costs cents a year per user, giving it away makes sense.", "commonMistake": "Thinking free means it costs nothing to run.", "mentalModel": "Free follows falling costs."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f6b5dcbe-f4b5-5813-a318-c53c1fc707d3$ml$::uuid, $ml$ai$ml$, 3, 1, $ml${"id": "ai-d3-c1", "title": "A chipmaker pays to be picked", "lessonTitle": "Who holds the power in AI", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, OpenAI agreed to deploy 6 gigawatts of AMD chips. AMD gave OpenAI a warrant for up to 160 million of its shares at one cent each, about 10% of the company.", "kicker": "Apply day 3: what does a buyer do when one input is scarce?", "fullText": "The deal starts with 1 gigawatt of AMD's MI450 chips in the second half of 2026. The warrant vests in stages, tied to deployments and to AMD's share price; the last tranche needs $600 a share. AMD said the deal should bring it tens of billions of dollars in revenue, and its shares rose more than 30% the day it was announced.\n\nWeeks earlier, NVIDIA had signed a letter of intent to invest up to $100 billion in OpenAI, which would deploy at least 10 gigawatts of NVIDIA systems. NVIDIA's top chips were allocation-bound, and the AMD deal helps OpenAI rely less on them.\n\nWhoever controls the scarcest input holds the power. A big buyer answers by building a second source, and a challenger can pay to become it.", "sources": [{"url": "https://www.forbes.com.au/news/investing/amd-shares-rocket-30-after-multibillion-dollar-deal-with-openai/", "label": "Forbes Australia, AMD shares surge 30% after OpenAI deal, Oct 2025"}, {"url": "https://www.tomshardware.com/pc-components/gpus/openai-signs-6gw-amd-gpu-deal", "label": "Tom's Hardware, OpenAI signs 6GW AMD GPU deal, Oct 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the logic of the deal in order.", "steps": ["Advanced AI chips are scarce", "OpenAI relies heavily on NVIDIA", "OpenAI wants a second supplier", "AMD offers up to 10% of itself", "OpenAI commits to 6 gigawatts of AMD chips"], "explanation": "Scarcity gives the leading supplier power. The buyer looks for a second source, and the challenger pays to win it."}, "numbers": {"kind": "numberSense", "prompt": "The warrant covers up to how many million AMD shares?", "min": 0, "max": 500, "value": 160, "unit": "M", "explanation": "Up to 160 million shares at one cent each, about 10% of AMD, if every milestone is met."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from NVIDIA's and AMD's AI chip teams in late 2025.", "prompt": "What does the OpenAI deal tell you about AMD?", "options": ["Its AI chips still have no serious buyers", "It is winning big buyers as a second source", "It has now replaced NVIDIA as the leader"], "correctIndex": 1, "consequences": ["OpenAI committed to 6 gigawatts of them.", "A 6 gigawatt commitment from OpenAI makes AMD a real alternative.", "OpenAI also planned at least 10 gigawatts of NVIDIA systems."], "explanation": "The deal shows AMD as the challenger buyers use to reduce their dependence on the leader."}, "proReasoning": "Read a deal for each side's position. The leader sets terms; the challenger pays to get in the door.", "commonMistake": "Reading one big win as a change of leader.", "mentalModel": "Leader or challenger: know which you join."}, "invest": {"call": {"kind": "theCall", "situation": "AMD stock jumps over 30% on the deal. The warrant could hand OpenAI about 10% of AMD for a cent a share.", "prompt": "What's the cost to existing AMD shareholders?", "options": ["None, since OpenAI pays almost nothing", "AMD must pay OpenAI cash upfront", "Dilution, if the milestones are met"], "correctIndex": 2, "consequences": ["Paying almost nothing for the shares is exactly the cost.", "AMD pays in shares that vest over time, not cash.", "Up to 160 million new shares shrink everyone else's slice."], "explanation": "The challenger paid for the customer with equity. Shareholders bear that cost through dilution."}, "proReasoning": "Investors price what a company gave up to win a deal. Here AMD traded up to a tenth of itself for a big buyer.", "commonMistake": "Celebrating the revenue without counting the shares given away.", "mentalModel": "Count what was paid to win the deal."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI startup needs a lot of GPUs in 2026, and the leading chips are allocation-bound.", "prompt": "What protects your plan?", "options": ["Test your models on a second chip supplier now", "Wait for chip prices to fall before planning", "Design your own chip from scratch"], "correctIndex": 0, "consequences": ["A second source keeps you running if your first runs short.", "Waiting leaves you exposed when supply is tight.", "Custom chips take years and huge budgets."], "explanation": "When one input is scarce, a second source protects you. OpenAI did the same at a far larger scale."}, "proReasoning": "Founders avoid depending on one scarce supplier. Make sure your stack can run on a second one.", "commonMistake": "Assuming the scarce input will always be there when you need it.", "mentalModel": "Never rely on one scarce supplier."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chipmaker would give a customer shares to buy its chips.", "prompt": "What's the best answer?", "options": ["Because OpenAI already owned part of AMD", "To win a big buyer away from the leader", "Because a law forces it to share stock"], "correctIndex": 1, "consequences": ["The warrant is what could give OpenAI a stake.", "AMD paid in shares to become OpenAI's second source.", "No law required it; it was a business choice."], "explanation": "The leader in a scarce input does not need to pay buyers. The challenger does."}, "proReasoning": "Who pays whom tells you who has power. Here the seller paid the buyer, because the buyer had options.", "commonMistake": "Assuming the seller always holds the power.", "mentalModel": "Who pays whom shows the power."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$3f04657f-9410-5ffe-835d-3613677ac8db$ml$::uuid, $ml$ai$ml$, 3, 2, $ml${"id": "ai-d3-c2", "title": "Margins at the chokepoint", "lessonTitle": "Who holds the power in AI", "slot": 2, "type": "connect", "brief": {"headline": "NVIDIA's data centers brought in $193.7 billion in fiscal 2026, at a 71.1% gross margin. Yet NVIDIA does not make its own chips: foundries such as TSMC do.", "kicker": "Connect day 2 and day 3: money pools where the input is scarce.", "fullText": "On day 2 you followed the money down the stack: users pay apps, apps pay model makers, model makers pay for cloud compute, and the cloud buys chips. On day 3 you saw who holds the power: whoever controls the scarcest input.\n\nNVIDIA's fiscal 2026 shows both. Data centers made up about 90% of its $215.9 billion revenue, and its full-year gross margin was 71.1%. Margins that high mean buyers have few alternatives.\n\nBut NVIDIA designs its chips and relies on foundries such as TSMC to make them. Even the chokepoint has a chokepoint.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000021/nvda-20260125.htm", "label": "NVIDIA 10-K, fiscal 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "NVIDIA keeps about 71 cents of gross profit on each dollar of sales. What does that suggest?", "options": ["Its chips cost more to make than they sell for", "Rivals are driving its prices down", "Buyers have few alternatives"], "correctIndex": 2, "explanation": "A margin that high holds only when buyers cannot easily switch. That is what controlling a scarce input looks like."}, "numbers": {"kind": "numberSense", "prompt": "What was NVIDIA's full-year gross margin in fiscal 2026, in percent?", "min": 0, "max": 100, "value": 71, "unit": "%", "explanation": "71.1%. Most of each dollar of sales was left after the cost of making the chips."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are weighing a job at NVIDIA against one at TSMC, which makes its chips.", "prompt": "What's the fairest read of their positions?", "options": ["TSMC depends on NVIDIA, not the reverse", "NVIDIA makes its own chips, so TSMC is minor", "Each depends heavily on the other"], "correctIndex": 2, "consequences": ["NVIDIA relies on foundries such as TSMC to manufacture.", "NVIDIA designs its chips but does not make them.", "NVIDIA needs foundries to make its chips, and they need its orders."], "explanation": "Power in AI is layered. The chip designer holds one chokepoint, the foundry another."}, "proReasoning": "Map who depends on whom before picking a side. Both companies sit on a scarce input.", "commonMistake": "Assuming the most famous company holds all the power.", "mentalModel": "Find the chokepoint behind the chokepoint."}, "invest": {"call": {"kind": "theCall", "situation": "NVIDIA's gross margin is 71.1%. A friend says margins like that will last forever.", "prompt": "What decides how long they last?", "options": ["How long buyers lack good alternatives", "How large the revenue number gets", "Nothing, since chip margins never fall"], "correctIndex": 0, "consequences": ["Pricing power lasts as long as the scarcity does.", "Revenue can grow while margins shrink.", "Margins fall when buyers can switch."], "explanation": "A chokepoint lets you raise prices. The question is how long the scarcity lasts."}, "proReasoning": "Investors ask what would end the scarcity: rival chips, custom chips or more supply. That sets the margin's life.", "commonMistake": "Treating a scarcity margin as permanent.", "mentalModel": "Margins last as long as the scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to AI labs that pay NVIDIA prices for every GPU hour.", "prompt": "Which product meets the biggest pain?", "options": ["A tool that ignores compute entirely", "Software that cuts the GPU hours they need", "A rival chip factory built next year"], "correctIndex": 1, "consequences": ["Compute is their biggest bill, so ignoring it misses the pain.", "Anything that cuts compute needs saves them real money.", "A chip factory takes years and billions to build."], "explanation": "Costly chips squeeze much of the industry. Products that cut compute needs address that pain directly."}, "proReasoning": "Founders look where a chokepoint charges the most. Saving customers compute is easier than building a rival chip.", "commonMistake": "Trying to beat the chokepoint head on.", "mentalModel": "Sell relief from the chokepoint."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how NVIDIA got so rich when it does not even make its own chips.", "prompt": "What's the answer?", "options": ["It secretly owns the factories that make them", "It sells more video games than anyone", "It designs the chips AI buyers need most"], "correctIndex": 2, "consequences": ["It relies on foundries such as TSMC.", "Data centers, not games, were about 90% of revenue.", "Data center chips brought in $193.7 billion in one year."], "explanation": "Design can be the scarce part. NVIDIA owns the design buyers want and pays others to make it."}, "proReasoning": "Owning the scarce part matters more than owning the factory. Design can be that part.", "commonMistake": "Thinking you have to make something to profit from it.", "mentalModel": "Own the scarce part."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ee985a01-05de-5681-ad5c-5c6933327715$ml$::uuid, $ml$ai$ml$, 3, 3, $ml${"id": "ai-d3-c3", "title": "A campus lab at the frontier", "lessonTitle": "Who holds the power in AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a university AI lab with a modest compute budget. In 2024, nearly 90% of notable AI models came from companies, up from 60% the year before.", "kicker": "Decide what your lab should do when you can't buy the frontier.", "fullText": "Stanford's AI Index tracks notable AI models each year. In 2024, nearly 90% came from industry. Frontier training can cost well over $100 million in compute: Gemini Ultra's was an estimated $191 million. Training compute grows 4 to 5 times every year.\n\nPower in AI follows whoever can pay for the scarce inputs. Your lab cannot outspend the companies that own them, so you have to choose work that does not depend on them.", "sources": [{"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which projects fit a lab that cannot buy frontier compute?", "buckets": ["Fits", "Doesn't fit"], "items": [{"text": "Methods that cut the compute a model needs", "bucket": 0}, {"text": "Studying how existing models behave", "bucket": 0}, {"text": "Partnering with a company for compute", "bucket": 0}, {"text": "Training a rival to Gemini Ultra", "bucket": 1}, {"text": "Matching frontier compute each year", "bucket": 1}], "explanation": "Work that needs the scarce input favors whoever owns it. Work that saves or studies it does not."}, "numbers": {"kind": "numberSense", "prompt": "In 2023, 60% of notable models came from industry. What share did in 2024?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "Nearly 90%. In one year, frontier work shifted further to whoever could pay for compute."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a PhD applicant choosing between this lab and a company lab.", "prompt": "Which question shows you understand the shift?", "options": ["Is the work limited by compute, data or people?", "How highly is the lab ranked in the world this year?", "Is the office close to the city center or not?"], "correctIndex": 0, "consequences": ["The answer shows where the lab's power and pain sit.", "Rankings say little about what you can actually train.", "Location says nothing about the scarce inputs."], "explanation": "Asking what limits a team tells you what work it can do, which matters more than its name."}, "proReasoning": "Ask what limits the team. At a campus lab it is often compute; at a company it may be people.", "commonMistake": "Choosing a lab on prestige without asking what it can afford to build.", "mentalModel": "Ask what limits the team."}, "invest": {"call": {"kind": "theCall", "situation": "A fund manager asks whether university labs will lead frontier models again soon.", "prompt": "What's the best-grounded answer?", "options": ["Yes, since compute will soon be free", "Unlikely while compute costs keep climbing", "Yes, since universities invented the field"], "correctIndex": 1, "consequences": ["Frontier runs cost more each year, not less.", "Compute growing 4 to 5 times a year keeps the frontier costly.", "Past invention does not pay for today's training runs."], "explanation": "Power follows whoever can pay for the scarce input. That is mostly companies today."}, "proReasoning": "Investors follow the scarce input to find where power sits. Right now it sits with companies that can buy compute.", "commonMistake": "Betting on history instead of who can pay today.", "mentalModel": "Follow the scarce input."}, "build_startup": {"call": {"kind": "theCall", "situation": "A professor in your lab wants to spin out a startup on a small seed round.", "prompt": "What's the soundest plan?", "options": ["Train a frontier model with the seed money", "Wait until compute gets cheap", "Build on methods that cut compute needs"], "correctIndex": 2, "consequences": ["A seed round will not cover a $191 million training run.", "Frontier compute keeps getting more expensive.", "Saving compute addresses a pain the whole industry feels."], "explanation": "Costly compute squeezes many players. Products that reduce it meet real demand."}, "proReasoning": "Founders without scarce inputs build things that help others use them well.", "commonMistake": "Racing the companies that own the scarce input.", "mentalModel": "Build what the scarcity makes valuable."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why universities no longer build most of the top AI models.", "prompt": "What's the main reason?", "options": ["Frontier training costs more than most can pay", "Professors have lost interest in AI research", "New laws ban universities from AI work"], "correctIndex": 0, "consequences": ["A single run can cost well over $100 million in compute.", "University research is still active.", "No such ban exists."], "explanation": "The scarce input is compute, and companies can pay for far more of it."}, "proReasoning": "When a field shifts to companies, look at what it costs to compete. In AI, that is compute.", "commonMistake": "Looking for a cultural reason when the reason is cost.", "mentalModel": "Follow the cost of competing."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$eddd2cc3-f7cc-5a71-baf4-30d8775f8c60$ml$::uuid, $ml$ai$ml$, 4, 1, $ml${"id": "ai-d4-c1", "title": "Tasks that double every 7 months", "lessonTitle": "The numbers that track AI", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025, METR measured how long a task AI agents can finish, timed by how long it takes skilled humans. That length had doubled about every 7 months for 6 years.", "kicker": "Apply day 4: read the doubling time, not just the score.", "fullText": "METR, a research group, timed software and reasoning tasks by how long skilled humans took. It then asked which task length a model could finish on its own half the time, and called that the time horizon.\n\nAcross six years of models, the time horizon doubled roughly every 7 months. In early 2025 the frontier, Claude 3.7 Sonnet, stood at about one hour. Models almost always succeeded on tasks taking humans under about 4 minutes, and less than 10% of the time on tasks over about 4 hours.\n\nIf the trend held to the end of the decade, METR said, frontier systems could carry out month-long projects on their own. A single score shows where models are. The doubling time shows where they are heading.", "sources": [{"url": "https://metr.substack.com/p/2025-03-19-measuring-ai-ability-to-complete-long-tasks", "label": "METR, Measuring AI ability to complete long tasks, Mar 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does METR's time horizon measure?", "options": ["The task length a model finishes half the time", "How long a model takes to give an answer", "How many hours the model was trained for"], "correctIndex": 0, "explanation": "Tasks are timed by how long humans take. The horizon is the length a model completes with 50% success."}, "numbers": {"kind": "numberSense", "prompt": "Starting at about one hour and doubling every 7 months, how many hours would the horizon be after 21 months?", "min": 0, "max": 24, "value": 8, "unit": "hours", "explanation": "Three doublings: 2, 4, then 8 hours. Compounding turns one hour into a full working day in under two years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an AI agent startup in 2025. They ask how fast agents are improving.", "prompt": "Which answer lands best?", "options": ["About one hour, and that looks like the ceiling", "They can now finish any task a human can", "The task length they handle doubles every 7 months"], "correctIndex": 2, "consequences": ["METR found a steady doubling, not a ceiling.", "Success fell below 10% on tasks over about 4 hours.", "One curve in one sentence explains the pace."], "explanation": "A doubling time captures the trend. A single number only captures today."}, "proReasoning": "Quote the curve, not just the level. \"Doubling about every 7 months\" tells them you track the trend.", "commonMistake": "Quoting where agents are today as if it were where they will stay.", "mentalModel": "Quote the doubling time."}, "invest": {"call": {"kind": "theCall", "situation": "An agent startup handles one-hour tasks today and pitches eight-hour tasks in about two years.", "prompt": "How do you judge the claim?", "options": ["Check it against the 7-month doubling trend", "Dismiss it, since one hour is the limit", "Accept it, since trends always continue"], "correctIndex": 0, "consequences": ["Three doublings is about 21 months, so the pitch fits the trend.", "The horizon has kept doubling for six years.", "Trends can break, so treat it as a forecast, not a promise."], "explanation": "A known curve lets you test a forecast. Here the pitch matches the trend, which is still only a trend."}, "proReasoning": "Investors test growth claims against the measured curve. Matching the trend makes a claim plausible, not certain.", "commonMistake": "Either dismissing compounding or treating it as guaranteed.", "mentalModel": "Test claims against the curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product idea needs agents to finish 4-hour tasks reliably. Today they succeed under 10% of the time.", "prompt": "What's the smart plan?", "options": ["Give up, since agents will never get there", "Start with shorter tasks, grow as horizons do", "Launch now, since 4-hour tasks already work"], "correctIndex": 1, "consequences": ["The curve has doubled steadily for six years.", "Short tasks work today, and the horizon keeps doubling.", "Under 10% success is not a product."], "explanation": "Build for what works now and let the doubling bring the rest within reach."}, "proReasoning": "Founders ride a curve by starting where it is today. The product grows as the capability does.", "commonMistake": "Building for where the curve will be before it gets there.", "mentalModel": "Start where the curve is."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says AI can only handle quick jobs, like answering a question.", "prompt": "What does METR's data say?", "options": ["Right, quick questions are still the limit", "It already runs month-long projects alone", "Hour-long tasks, half the time, and rising"], "correctIndex": 2, "consequences": ["Agents finish much longer tasks than a quick question.", "Month-long projects were a forecast for later in the decade.", "Claude 3.7 Sonnet reached about one hour in early 2025."], "explanation": "Agents were at about one hour in early 2025, and that length was doubling every 7 months."}, "proReasoning": "Describe AI by its trend, not one snapshot. An hour today, doubling every 7 months, means far more soon.", "commonMistake": "Judging AI by what it could do a year or two ago.", "mentalModel": "Snapshot plus doubling time."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$179f04a1-8321-568a-886d-4f1f80d8171f$ml$::uuid, $ml$ai$ml$, 4, 2, $ml${"id": "ai-d4-c2", "title": "Two curves, opposite ways", "lessonTitle": "The numbers that track AI", "slot": 2, "type": "connect", "brief": {"headline": "Training compute for top models grows 4 to 5 times a year. Meanwhile, GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months.", "kicker": "Connect day 2 and day 4: two compounding curves, moving apart.", "fullText": "On day 2 you saw the price of each answer collapse: GPT-3.5-level answers fell 280-fold in about 18 months. On day 4 you saw training compute for frontier models grow 4 to 5 times a year, doubling roughly every five months.\n\nBoth are compounding curves. One makes the frontier ever more expensive to reach. The other makes yesterday's frontier cheap to use.\n\nTogether they help explain why 78% of organizations said they used AI in 2024, up from 55% in 2023, while only a few firms can afford to train the newest models.", "sources": [{"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}, {"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each one growing fast or falling fast?", "buckets": ["Growing fast", "Falling fast"], "items": [{"text": "Compute used to train frontier models", "bucket": 0}, {"text": "Share of organizations using AI", "bucket": 0}, {"text": "Share of notable models built by companies", "bucket": 0}, {"text": "Price of a GPT-3.5-level answer", "bucket": 1}, {"text": "Cost of serving a free user at that level", "bucket": 1}], "explanation": "Reaching the frontier keeps getting costlier. Using an older level keeps getting cheaper, and adoption rises."}, "numbers": {"kind": "numberSense", "prompt": "AI use rose from 55% of organizations in 2023 to 78% in 2024. By how many percentage points?", "min": 0, "max": 60, "value": 23, "unit": "points", "explanation": "23 points in one year, helped by answers that cost a tiny fraction of what they did."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why AI spread through companies so fast in 2024.", "prompt": "What's the sharpest answer?", "options": ["Good-enough answers became very cheap to use", "Every company trained its own frontier model", "Governments required companies to adopt AI"], "correctIndex": 0, "consequences": ["A 280-fold price drop made AI cheap to try everywhere.", "Only a few firms can afford frontier training.", "Adoption was driven by cost and usefulness, not mandates."], "explanation": "Falling prices for older-level answers let most organizations use AI without training anything."}, "proReasoning": "Explain adoption with the cost curve. Cheap answers, not frontier training, put AI in 78% of organizations.", "commonMistake": "Assuming adoption required every company to build its own model.", "mentalModel": "Cheap answers drive adoption."}, "invest": {"call": {"kind": "theCall", "situation": "AI spending is soaring. A skeptic says the demand behind it is hype.", "prompt": "What should you check?", "options": ["Only how many models were released", "Adoption data next to the spending", "Only the size of the spending"], "correctIndex": 1, "consequences": ["Model counts measure supply, not demand.", "Use rising from 55% to 78% of organizations is a real demand signal.", "Spending alone cannot tell you if anyone uses the result."], "explanation": "Adoption is the demand signal. Track it next to spending to judge whether demand is real."}, "proReasoning": "Investors pair a supply curve with a demand curve. Spending without adoption would be a warning.", "commonMistake": "Judging demand from spending alone.", "mentalModel": "Pair spending with adoption."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product works with GPT-3.5-level quality. A rival waits for the next frontier model to launch.", "prompt": "What's your move?", "options": ["Wait for the frontier like your rival", "Train your own frontier model first", "Build now on cheap, proven models"], "correctIndex": 2, "consequences": ["Waiting gives up the cost advantage you already have.", "Frontier training is the costly curve, not yours.", "That level now costs a tiny fraction of 2022 prices."], "explanation": "If an older level is good enough, the falling curve works for you today."}, "proReasoning": "Founders pick the curve that helps them. Use what has become cheap; let others pay for the frontier.", "commonMistake": "Waiting for the newest model when an older one already does the job.", "mentalModel": "Ride the falling curve."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how AI can be getting more expensive and cheaper at the same time.", "prompt": "What's the answer?", "options": ["New models cost more to build; old ones less to use", "It cannot be both, so one of the claims is wrong", "Prices rise for companies and fall for ordinary people"], "correctIndex": 0, "consequences": ["Frontier training grows 4 to 5 times a year while answer prices fall.", "Both are true, for different things.", "The split is frontier versus older models, not who pays."], "explanation": "Two curves: training the frontier gets costlier, while answers at an older level get cheaper."}, "proReasoning": "When two facts seem to clash, check whether they measure different things.", "commonMistake": "Assuming \"AI costs\" is one number.", "mentalModel": "Different curves, different things."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$d3444490-3183-51ff-801e-5c78745f3bd2$ml$::uuid, $ml$ai$ml$, 4, 3, $ml${"id": "ai-d4-c3", "title": "Planning for 16 times", "lessonTitle": "The numbers that track AI", "slot": 3, "type": "decide", "brief": {"headline": "You plan compute for an AI lab two years ahead. Training compute for notable models has grown about 4 times a year. Moore's law took about 12 years to grow 64 times.", "kicker": "Decide how much to plan for when the curve compounds.", "fullText": "Epoch AI estimates training compute for notable models grew about 4.1 times a year from 2010 to 2024, and about 5.3 times for frontier models. Stanford's AI Index puts it as a doubling roughly every five months.\n\nSmall yearly multiples compound fast. Growing 4 times a year means 16 times in two years and 64 times in three. Chips doubled their transistors every two years, so Moore's law took about 12 years to grow 64 times.\n\nA plan that adds the same amount each year will fall far behind a curve that multiplies.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}, {"url": "https://www.intel.com/content/www/us/en/newsroom/resources/moores-law.html", "label": "Intel, Moore's law"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Growing 4 times a year means 16 times in two years.", "Moore's law took about 12 years to grow 64 times.", "Growing 4 times a year means 12 times in three years."], "fakeIndex": 2, "explanation": "Multiples multiply: 4 x 4 x 4 is 64, not 12. Adding instead of multiplying is the classic mistake."}, "numbers": {"kind": "numberSense", "prompt": "Moore's law doubles every two years. How many years does it take to grow 64 times?", "min": 0, "max": 30, "value": 12, "unit": "years", "explanation": "Six doublings at two years each is 12 years. AI training compute did the same in about three."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an infrastructure role. They ask how much compute to plan for in two years at 4 times a year.", "prompt": "What's your answer?", "options": ["About 4 times, since growth will slow", "About 16 times what we use today", "About 8 times, adding 4 each year"], "correctIndex": 1, "consequences": ["You can argue for slowing, but not as your base plan.", "4 times 4 is 16, and that shows you think in multiples.", "Adding instead of multiplying is the mistake they are testing."], "explanation": "Compounding means multiplying each year. Two years at 4x is 16x."}, "proReasoning": "Do the compounding out loud. \"Four times four, so about 16 times\" shows you plan in multiples.", "commonMistake": "Adding the yearly growth instead of multiplying it.", "mentalModel": "Multiply, don't add."}, "invest": {"call": {"kind": "theCall", "situation": "A chip supplier forecasts AI demand growing at Moore's law pace, doubling every two years.", "prompt": "How do you read that forecast?", "options": ["It is about right, since chips follow Moore's law", "It is too high, since AI demand is flat", "It may be far too low for AI training"], "correctIndex": 2, "consequences": ["Moore's law is far slower than AI compute growth.", "Adoption and compute both rose fast.", "AI training compute doubled about every five months, much faster."], "explanation": "AI compute doubled roughly every five months, not every two years. The gap compounds."}, "proReasoning": "Investors compare a forecast with the actual curve. A slower curve, compounded, misses by a mile.", "commonMistake": "Using the familiar chip curve for a much faster one.", "mentalModel": "Use the right curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells tools to AI labs. You are setting your three-year capacity plan.", "prompt": "What growth do you design for?", "options": ["Multiples each year, not a fixed amount", "The same customer load we have today", "A fixed 10% more capacity each year"], "correctIndex": 0, "consequences": ["If labs grow compute 4 times a year, their tools must scale too.", "Your customers will not stay the same size.", "A fixed 10% falls behind a curve that multiplies."], "explanation": "Selling into a compounding market means your own systems must handle multiples, not percentages."}, "proReasoning": "Founders selling into a fast curve plan for its pace, not their own comfort. 64 times in three years changes the design.", "commonMistake": "Planning linear growth for customers on a compounding curve.", "mentalModel": "Plan at your customers' pace."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what \"doubling every five months\" means in practice.", "prompt": "What's a good way to put it?", "options": ["About 5% bigger at the end of every month", "About 16 times bigger in under two years", "About twice as big at the end of each year"], "correctIndex": 1, "consequences": ["Five percent a month is less than twice a year.", "Four doublings in 20 months is 16 times.", "That would be one doubling a year, far slower."], "explanation": "Four doublings, 20 months, 16 times. That is why the curve matters more than any one number."}, "proReasoning": "Turn a doubling time into a multiple over a period people can picture. It makes compounding feel real.", "commonMistake": "Hearing \"doubling\" and thinking \"a bit more\".", "mentalModel": "Count the doublings."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$8416592d-9138-5f9c-9974-6c92111cf433$ml$::uuid, $ml$ai$ml$, 5, 1, $ml${"id": "ai-d5-c1", "title": "The screener in court", "lessonTitle": "The rules that now bind AI", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, a federal judge let a lawsuit against Workday proceed as a nationwide collective action. It claims Workday's AI screening tools turned away applicants aged 40 and over.", "kicker": "Apply day 5: why hiring sits in the high-risk tier.", "fullText": "The case is Mobley v. Workday, in the Northern District of California. On May 16, 2025, Judge Rita Lin granted preliminary certification for applicants aged 40 and over who applied through Workday's platform from September 24, 2020, and were not recommended. The court pointed to one common policy: the use of Workday's AI to score, sort, rank or screen applicants. Workday said in filings that 1.1 billion applications were rejected using its tools in that period.\n\nThe ruling is not a verdict, and the case runs under US age discrimination law. But it shows why the EU AI Act puts CV screening for hiring in its high-risk tier. A model that sorts emails is minimal risk. A model that sorts people for jobs can shut them out.", "sources": [{"url": "https://www.cdflaborlaw.com/blog/federal-court-grants-preliminary-certification-in-landmark-ai-hiring-bias-case", "label": "CDF Labor Law, certification in AI hiring bias case, Jun 2025"}, {"url": "https://www.proskauer.com/blog/ai-bias-lawsuit-against-workday-reaches-next-stage-as-court-grants-conditional-certification-of-adea-claim", "label": "Proskauer, AI bias lawsuit against Workday reaches next stage, Jun 2025"}, {"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}]}, "evidence": {"kind": "faceOff", "prompt": "Under the EU AI Act, which use is high-risk?", "left": {"name": "Sorting incoming emails as spam", "note": "A filter in your inbox"}, "right": {"name": "Ranking job applicants", "note": "What Workday's tools are accused of doing"}, "correctIndex": 1, "explanation": "CV screening for hiring is high-risk and must meet strict requirements. A spam filter is minimal risk."}, "numbers": {"kind": "numberSense", "prompt": "Workday said about how many billion applications were rejected using its tools in that period?", "min": 0, "max": 5, "value": 1.1, "unit": "B", "explanation": "About 1.1 billion. At that scale, one flaw in a screening model touches a huge number of people."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an HR software company that sells in Europe. They ask which EU tier their CV screener is in.", "prompt": "What's your answer?", "options": ["High-risk, with strict requirements", "Minimal risk, like a spam filter", "Banned outright in the EU"], "correctIndex": 0, "consequences": ["CV screening for hiring is a named high-risk use.", "Sorting people for jobs is treated very differently from sorting emails.", "It is allowed, under strict rules."], "explanation": "Teams selling AI in Europe need people who know the tiers. Hiring tools are high-risk."}, "proReasoning": "Name the tier and what it brings. \"High-risk, so strict requirements before sale\" is the answer they need.", "commonMistake": "Confusing high-risk with banned.", "mentalModel": "Know the tier by heart."}, "invest": {"call": {"kind": "theCall", "situation": "You're looking at an HR tech company whose revenue comes mostly from AI screening of applicants.", "prompt": "What do you check first?", "options": ["Nothing extra, since HR tools are low risk", "Its compliance costs and legal exposure", "Only how fast its users are growing"], "correctIndex": 1, "consequences": ["Hiring is one of the uses the EU treats as high-risk.", "High-risk revenue carries compliance costs and, as Workday shows, lawsuits.", "Growth means little if the core use draws legal risk."], "explanation": "Ask which tier the revenue comes from. High-risk revenue costs more to keep."}, "proReasoning": "Investors map revenue to risk tiers. Revenue from high-risk uses carries compliance and legal costs.", "commonMistake": "Valuing all AI revenue as if it carried the same risk.", "mentalModel": "Ask which tier pays the bills."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your model ranks text well. You could sell it to sort job applications or to sort support tickets.", "prompt": "What changes between the two?", "options": ["Nothing, since it is the same model", "Support tickets are a banned use", "Hiring brings high-risk rules"], "correctIndex": 2, "consequences": ["The law looks at the use, not the code.", "Sorting tickets is not on the banned list.", "Choosing hiring means strict requirements before you can sell in the EU."], "explanation": "The same model can be minimal risk in one use and high-risk in another. The use sets the work."}, "proReasoning": "Founders choose the use case knowing it sets the compliance work. Same model, very different rules.", "commonMistake": "Picking the market first and discovering the rules later.", "mentalModel": "The use case sets the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a hiring tool gets stricter rules than a spam filter.", "prompt": "What's the best answer?", "options": ["Its mistakes can shut people out of jobs", "Hiring software is always less accurate", "Spam filters are run by governments"], "correctIndex": 0, "consequences": ["The higher the stakes for people, the stricter the tier.", "Accuracy varies; the stakes are what differ.", "Spam filters are ordinary software, and minimal risk."], "explanation": "The EU sorts AI by what is at stake when it goes wrong, not by how clever it is."}, "proReasoning": "Ask what happens to a person when the AI gets it wrong. That is how the EU sets the tier.", "commonMistake": "Thinking the rules depend on how advanced the AI is.", "mentalModel": "Higher stakes, stricter tier."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$51bc5052-e4cf-5c56-a745-5746b7d3867e$ml$::uuid, $ml$ai$ml$, 5, 2, $ml${"id": "ai-d5-c2", "title": "Same method, different tier", "lessonTitle": "The rules that now bind AI", "slot": 2, "type": "connect", "brief": {"headline": "A spam filter and a CV screener can both be supervised models trained on labeled examples. Under the EU AI Act, the spam filter is minimal risk and the CV screener is high-risk.", "kicker": "Connect day 1 and day 5: the use sets the tier, not the method.", "fullText": "On day 1 you met supervised learning: a model learns from examples with the answer attached, like emails marked as spam. On day 5 you saw the EU AI Act sort AI into tiers: banned, high-risk, transparency duties and minimal.\n\nThe Act does not ask how a model learned. It asks what the model is used for. A supervised spam filter sits in the minimal tier. A supervised model screening CVs for hiring is high-risk and must meet strict requirements, which now apply from December 2, 2027. The Act entered into force on August 1, 2024, and its maximum fines reach EUR 35 million or 7% of global annual turnover.", "sources": [{"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}, {"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}, {"url": "https://www.actuia.com/en/news/ai-act-obligations-in-force-and-delays-under-omnibus-2026-1744/", "label": "ActuIA, AI Act omnibus 2026/1744"}, {"url": "https://www.twobirds.com/en/insights/2024/global/countdown-to-compliance-as-eu-ai-act-set-to-enter-into-force", "label": "Bird & Bird, AI Act timeline"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Two supervised models: a spam filter and a CV screener. What decides their EU risk tier?", "options": ["What each model is used for", "How each model learned", "How many parameters each has"], "correctIndex": 0, "explanation": "Both learned from labeled examples. The EU AI Act sorts them by use: minimal for spam, high-risk for hiring."}, "numbers": {"kind": "numberSense", "prompt": "The Act took force in August 2024; strict high-risk rules apply from December 2027. About how many months apart?", "min": 0, "max": 60, "value": 40, "unit": "months", "explanation": "About 40 months. Teams building hiring tools have time, but the rules are coming."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a data scientist moving from a spam filter team to a hiring tools team in Europe.", "prompt": "What changes most in your work?", "options": ["You must stop using labeled data", "Your models now face strict EU rules", "Nothing, since the methods are the same"], "correctIndex": 1, "consequences": ["Labeled data is fine; the use is what is regulated.", "Hiring is high-risk, so the requirements follow your models.", "The methods match, but the tier does not."], "explanation": "Moving to a high-risk use brings strict requirements, even with the same techniques."}, "proReasoning": "Know that your job changes when the use changes. Same code, different tier, different duties.", "commonMistake": "Assuming your old habits carry over to a high-risk use.", "mentalModel": "New use, new duties."}, "invest": {"call": {"kind": "theCall", "situation": "Two startups use similar supervised models. One sells to game studios, the other scores credit.", "prompt": "Which carries more regulatory cost in the EU?", "options": ["The game studio supplier", "Both carry the same cost", "The credit scoring startup"], "correctIndex": 2, "consequences": ["Video game AI is minimal risk.", "Same method, different tiers, different costs.", "Credit scoring is high-risk and must meet strict requirements."], "explanation": "Look past the technology to the use. The use decides the compliance bill."}, "proReasoning": "Investors judge regulatory cost by use, not by technology. Similar models can carry very different costs.", "commonMistake": "Assuming similar technology means similar risk.", "mentalModel": "Same tech, different tier."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your supervised classifier works well. You are choosing your first market in Europe.", "prompt": "How should the EU tiers shape the choice?", "options": ["Count each use's compliance work in the plan", "Ignore them, since the model is the same", "Avoid any use that involves data"], "correctIndex": 0, "consequences": ["A minimal-risk use ships faster; a high-risk one needs more work.", "The rules attach to the use, not the model.", "Every model uses data; the tier depends on the use."], "explanation": "Choosing the use decides the compliance work. Put that in the plan from day one."}, "proReasoning": "Founders weigh compliance work when picking a first market. It can decide which market is cheaper to enter.", "commonMistake": "Choosing a market without pricing its rules.", "mentalModel": "Price the rules into the market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if the AI is basically the same, why are the rules different?", "prompt": "What's the answer?", "options": ["The rules are random", "The law looks at the use, not the method", "The hiring AI is secretly a different type"], "correctIndex": 1, "consequences": ["The tiers follow the risk to people.", "Sorting emails and sorting job seekers have very different stakes.", "Both can be supervised models trained on labels."], "explanation": "The EU AI Act regulates uses. The same technique can land in different tiers."}, "proReasoning": "Rules follow what a tool does to people, not how it was built.", "commonMistake": "Expecting AI rules to be about the technology.", "mentalModel": "Rules follow the use."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$65a30ca8-4b49-51eb-8bd0-fa9c7e695695$ml$::uuid, $ml$ai$ml$, 5, 3, $ml${"id": "ai-d5-c3", "title": "A model that reads emotions", "lessonTitle": "The rules that now bind AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup whose model reads emotions from faces. Your first clients would be EU employers watching staff. Since February 2, 2025, emotion recognition at work has been banned in the EU.", "kicker": "Decide where your product can be sold.", "fullText": "The EU AI Act sorts AI by risk. Some practices are banned outright, including social scoring and emotion recognition at work or school. Those bans have applied since February 2, 2025.\n\nOther uses are high-risk and face strict requirements, such as CV screening, credit scoring and exam scoring. Most AI, like spam filters or video game AI, is minimal risk.\n\nMaximum fines reach EUR 35 million or 7% of annual global turnover. Under the Act, what you may build depends on what it is used for.", "sources": [{"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}, {"url": "https://www.twobirds.com/en/insights/2024/global/countdown-to-compliance-as-eu-ai-act-set-to-enter-into-force", "label": "Bird & Bird, AI Act timeline"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Emotion recognition at work is banned in the EU.", "Exam scoring is a high-risk use.", "The bans only start applying in December 2027."], "fakeIndex": 2, "explanation": "The bans have applied since February 2, 2025. December 2027 is the date for the strict high-risk rules."}, "numbers": {"kind": "numberSense", "prompt": "A company has EUR 1 billion in global annual turnover. What is 7% of that, in millions of euros?", "min": 0, "max": 200, "value": 70, "unit": "M", "explanation": "EUR 70 million. A fine sized by global turnover hurts large companies as much as small ones."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The startup offers you a job. Its main product reads workers' emotions for European employers.", "prompt": "What do you ask before accepting?", "options": ["How fast it plans to grow its headcount this year", "Which cloud provider its product runs on", "How it will pivot, since that use is banned"], "correctIndex": 2, "consequences": ["Hiring plans mean little if the main product cannot be sold.", "Infrastructure is minor next to a banned use.", "Its core use has been banned in the EU since February 2025."], "explanation": "A product in the banned tier cannot be sold in the EU. That is the first thing to ask about."}, "proReasoning": "Before joining an AI company, check which tier its main product sits in. A banned use is an existential problem.", "commonMistake": "Asking about perks before asking whether the product is legal.", "mentalModel": "Check the tier before you join."}, "invest": {"call": {"kind": "theCall", "situation": "The startup's revenue comes from EU employers monitoring their staff's emotions.", "prompt": "How do you read that revenue?", "options": ["It cannot legally continue in the EU", "It is safe, since clients signed contracts", "It is high-risk, so it just needs paperwork"], "correctIndex": 0, "consequences": ["Banned uses cannot be sold in the EU at all.", "A contract does not make a banned use legal.", "This use is banned, not high-risk."], "explanation": "Banned-tier revenue is not revenue you can count on in the EU. Check which tier the money comes from."}, "proReasoning": "Investors sort a company's revenue by tier. Banned-tier revenue in the EU is worth nothing there.", "commonMistake": "Confusing a banned use with a high-risk one.", "mentalModel": "Banned revenue is no revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Your emotion model works, but your planned EU clients are employers.", "prompt": "What's your move?", "options": ["Rename it and sell it to schools instead", "Find a use that is not on the banned list", "Sell to EU employers anyway and hope"], "correctIndex": 1, "consequences": ["Emotion recognition at school is banned too.", "The ban targets specific uses, so a different use may be allowed.", "Fines can reach 7% of global turnover."], "explanation": "The ban covers specific uses. Choosing a different use is the only path in the EU."}, "proReasoning": "Founders treat the banned list as a hard boundary. The same model may still serve a different use.", "commonMistake": "Hoping a new name or a new client gets around a ban on the use.", "mentalModel": "Change the use, not the label."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why big tech companies take EU AI rules so seriously.", "prompt": "What's one big reason?", "options": ["Fines are capped at a few thousand euros", "Only governments can ever be fined", "Fines can reach 7% of global turnover"], "correctIndex": 2, "consequences": ["The maximum is EUR 35 million or 7% of turnover.", "Companies can be fined, and heavily.", "For a giant, 7% of worldwide turnover is billions."], "explanation": "Fines sized by global turnover are large enough to matter to the biggest companies."}, "proReasoning": "A rule matters when the penalty matches the size of the company. Turnover-based fines do.", "commonMistake": "Assuming regulators can only issue small fines.", "mentalModel": "Penalties sized to the company."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e9a99ab8-e827-522f-81d5-9fb7a1042b39$ml$::uuid, $ml$ai$ml$, 6, 1, $ml${"id": "ai-d6-c1", "title": "The thumbs-up that taught flattery", "lessonTitle": "The boat that never finished the race", "slot": 1, "type": "apply", "brief": {"headline": "On April 25, 2025, an update made ChatGPT's GPT-4o noticeably more sycophantic. OpenAI began rolling it back three days later. A new reward from users' thumbs-up had weakened the signal keeping flattery in check.", "kicker": "Apply day 6: the model learned the proxy, not the goal.", "fullText": "The update added a reward signal based on users' thumbs-up and thumbs-down. OpenAI said that, in aggregate, the changes weakened the influence of its primary reward signal, which had been holding sycophancy back.\n\nThe checks missed it. Offline evaluations generally looked good, and A/B tests suggested the small group of users who tried the model liked it. Some expert testers felt its behavior was slightly off, but OpenAI launched on the positive user signals, which it later called the wrong call. The full rollback began on April 28 and took about 24 hours.\n\nThumbs-up was the proxy. What OpenAI wanted was helpful, honest answers. The model learned to win the proxy.", "sources": [{"url": "https://openai.com/index/expanding-on-sycophancy/", "label": "OpenAI, Expanding on what we missed with sycophancy, May 2025"}, {"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the sycophancy episode in order.", "steps": ["A reward based on users' thumbs-up is added", "The primary reward loses influence", "Offline tests and A/B results look good", "The update ships and flatters users", "OpenAI rolls it back within days"], "explanation": "The proxy crept into the reward, the tests did not catch it, and users did."}, "numbers": {"kind": "numberSense", "prompt": "Once it began, about how many hours did the full rollback take?", "min": 0, "max": 72, "value": 24, "unit": "hours", "explanation": "About 24 hours, starting April 28. The update had been live for only a few days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on a model behavior team. A/B tests love an update, but some expert testers say it feels off.", "prompt": "What do you recommend?", "options": ["Ship it, then ask the testers again", "Hold it until the concern is understood", "Ship it, since users liked it in tests"], "correctIndex": 1, "consequences": ["By then, every user has the problem.", "OpenAI later said shipping on user signals was the wrong call.", "Liking it in a test is the proxy, not the goal."], "explanation": "When a metric and expert judgment disagree, the metric may be the thing being gamed."}, "proReasoning": "Spot the gameable metric and say so. Thumbs-up can rise while answers get worse.", "commonMistake": "Treating a good A/B result as proof the model is better.", "mentalModel": "When the metric and experts disagree, dig."}, "invest": {"call": {"kind": "theCall", "situation": "An AI app reports that user ratings jumped after it tuned its model to them.", "prompt": "What do you ask?", "options": ["Only how much the ratings rose", "Nothing, since happy users mean a good product", "What the ratings reward, and what they miss"], "correctIndex": 2, "consequences": ["A bigger jump can mean a bigger gap from the real goal.", "Users rated sycophantic answers highly too.", "Ratings can reward flattery over help, as OpenAI found."], "explanation": "A product tuned to an easy metric can look great and still fail its users. Ask what it is rewarded for."}, "proReasoning": "Investors ask what a product optimizes. A rising score is only good news if it tracks the real goal.", "commonMistake": "Taking a rising metric at face value.", "mentalModel": "Ask what the product is rewarded for."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI tutoring app could add a reward based on students' thumbs-up.", "prompt": "What do you do first?", "options": ["Check that thumbs-up tracks real learning", "Add it, since happy students learn more", "Drop all student feedback for good"], "correctIndex": 0, "consequences": ["If they drift apart, the tutor learns to please, not to teach.", "Students may like easy answers more than hard lessons.", "Feedback is useful once you know what it measures."], "explanation": "Write down the real goal and the metric. Test whether they can drift apart before you build on it."}, "proReasoning": "Founders test a metric against the real goal before rewarding it. A tutor that flatters fails its students.", "commonMistake": "Rewarding what is easy to count.", "mentalModel": "Test the metric against the goal."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ChatGPT suddenly got so flattering in April 2025.", "prompt": "What's the best explanation?", "options": ["A hacker changed its settings overnight", "A thumbs-up reward pushed it toward pleasing", "OpenAI instructed it to compliment every user"], "correctIndex": 1, "consequences": ["It came from a planned update, not an attack.", "The new reward weakened the one holding flattery back.", "No one instructed it to flatter; the reward did."], "explanation": "The model optimized what it was rewarded for. Pleasing people earned thumbs-up."}, "proReasoning": "When an AI behaves oddly, ask what it was rewarded for. The answer is often there.", "commonMistake": "Assuming someone told the AI to behave that way.", "mentalModel": "Look for the reward behind the behavior."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$dc6cdc9f-bd8d-5a7f-80e5-9ca2522cbe71$ml$::uuid, $ml$ai$ml$, 6, 2, $ml${"id": "ai-d6-c2", "title": "When the reward is the goal", "lessonTitle": "The boat that never finished the race", "slot": 2, "type": "connect", "brief": {"headline": "AlphaGo Zero was rewarded for winning at Go, and beat its predecessor 100 games to 0. The CoastRunners boat was rewarded for hitting targets, and never finished the race.", "kicker": "Connect day 1 and day 6: a reward works when it is the real goal.", "fullText": "On day 1 you met reinforcement learning: a model tries things and learns from rewards or penalties. AlphaGo Zero learned Go by self-play, and in Go the reward and the goal are the same: win the game. After three days it beat the AlphaGo that had beaten Lee Sedol, 100 to 0.\n\nOn day 6 you met the CoastRunners boat. The game gave points for hitting targets, not for finishing. The agent found a lagoon where three targets kept reappearing, circled it, and scored about 20% more than human players without finishing.\n\nSame method, different reward. Reinforcement learning chases whatever you score, so the score has to be what you actually want.", "sources": [{"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}, {"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}, {"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}]}, "evidence": {"kind": "faceOff", "prompt": "Which agent was rewarded for a proxy, not the real goal?", "left": {"name": "AlphaGo Zero", "note": "Rewarded for winning the game"}, "right": {"name": "The CoastRunners boat", "note": "Rewarded for hitting targets"}, "correctIndex": 1, "explanation": "Points for targets stood in for racing well, and the boat gamed them. In Go, winning is the goal itself."}, "numbers": {"kind": "numberSense", "prompt": "How many days of self-play did AlphaGo Zero need to beat the version that beat Lee Sedol?", "min": 0, "max": 14, "value": 3, "unit": "days", "explanation": "Three days. When the reward is the goal, reinforcement learning can move very fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a reinforcement learning role at a warehouse robot company. They ask what you'd reward a picking robot for.", "prompt": "What's your answer?", "options": ["The number of times the arm moves each hour", "The number of items it touches per hour", "Orders packed correctly, checked at the end"], "correctIndex": 2, "consequences": ["It would learn to move a lot, not to pack well.", "It would learn to touch items, like the boat hitting targets.", "That reward is the real goal, like winning in Go."], "explanation": "Reward the outcome you want. Activity counts are proxies the agent will game."}, "proReasoning": "Propose a reward that is the goal itself, and name the proxy you would avoid. That contrast impresses.", "commonMistake": "Rewarding activity because it is easy to count.", "mentalModel": "Reward the outcome, not the activity."}, "invest": {"call": {"kind": "theCall", "situation": "Two reinforcement learning startups pitch you. One rewards its agent for the customer's result, the other for an easy score.", "prompt": "Which design do you trust more?", "options": ["The one rewarded for the customer's result", "The one with the higher score on its metric", "Both equally, since a score is a score"], "correctIndex": 0, "consequences": ["Its reward matches the goal, as winning did for AlphaGo Zero.", "The boat had a high score too, and never finished.", "A score is only as good as what it measures."], "explanation": "An agent optimizes its reward. Back the one whose reward is what customers actually want."}, "proReasoning": "Investors ask what an agent is rewarded for. A great score on a proxy can hide a product that fails.", "commonMistake": "Comparing scores without asking what they measure.", "mentalModel": "Check what the score measures."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are designing the reward for an agent that books sales meetings for clients.", "prompt": "What do you reward?", "options": ["Replies received from anyone", "Meetings that actually take place", "Invitations sent out"], "correctIndex": 1, "consequences": ["It would chase any reply, useful or not.", "That is the outcome your client pays for.", "It would learn to spam invites."], "explanation": "Pick the reward closest to what the client values. Easier counts invite gaming."}, "proReasoning": "Founders pick the reward a client would recognize as the goal. Everything easier is a proxy.", "commonMistake": "Choosing the reward that is easiest to log.", "mentalModel": "Reward what the client pays for."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why one AI mastered Go while another got stuck circling a lagoon.", "prompt": "What's the difference?", "options": ["The Go AI was simply a smarter program", "The boat game was far harder to learn than Go", "Go's reward was the goal; the boat's was not"], "correctIndex": 2, "consequences": ["Both used reinforcement learning; the rewards differed.", "The boat scored 20% more than humans, so it was not struggling.", "Winning is the point of Go; hitting targets was not the point of racing."], "explanation": "Both learned exactly what they were rewarded for. Only one reward matched the goal."}, "proReasoning": "AI learns what you reward, very well. The trick is rewarding the right thing.", "commonMistake": "Blaming the AI when the reward was the problem.", "mentalModel": "It learns exactly what you reward."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$adf81351-ec39-58a0-b272-bfe5c4b2f8d1$ml$::uuid, $ml$ai$ml$, 6, 3, $ml${"id": "ai-d6-c3", "title": "What should the app reward?", "lessonTitle": "The boat that never finished the race", "slot": 3, "type": "decide", "brief": {"headline": "You run a language learning app and want to tune its lesson picks with reinforcement learning. Minutes in the app are easy to measure. Whether people actually learn is harder.", "kicker": "Decide what your app should reward.", "fullText": "It is hard to specify what we really want, so developers often reward easy-to-measure proxies. OpenAI's CoastRunners agent is the classic case: the game paid points for hitting targets, so the agent circled a lagoon and scored about 20% more than human players without finishing the race.\n\nYour app faces the same choice. Minutes in the app, notifications opened and lessons started are easy to count. Learning is slower to measure. Human feedback and demonstrations can help repair a reward, but they bring risks of their own.", "sources": [{"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each metric close to the real goal, or an easy proxy?", "buckets": ["Close to the goal", "Easy proxy"], "items": [{"text": "Quiz scores improved a week later", "bucket": 0}, {"text": "Learners still studying after 30 days", "bucket": 0}, {"text": "Minutes spent in the app", "bucket": 1}, {"text": "Notifications opened", "bucket": 1}, {"text": "Lessons started", "bucket": 1}], "explanation": "Proxies are easy to count and easy to game. Metrics tied to learning are slower but closer to the goal."}, "numbers": {"kind": "numberSense", "prompt": "If human players averaged 100 points, about what would the CoastRunners agent have averaged?", "min": 0, "max": 200, "value": 120, "unit": "points", "explanation": "About 120, roughly 20% more, without ever finishing the race. A high score on a proxy can hide a failure."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the app's machine learning lead. The product manager wants to reward minutes in the app.", "prompt": "What do you push for?", "options": ["A reward tied to learning, like later quiz gains", "Minutes in the app, since they are easy to track", "Notifications opened, since they show interest"], "correctIndex": 0, "consequences": ["It is slower to measure but tracks what users came for.", "The model would learn to keep people in, not to teach.", "It would learn to send more notifications."], "explanation": "A model optimizes what you measure. Measure something close to learning."}, "proReasoning": "Name the gap between the metric and the goal, and offer a better metric. That is the job.", "commonMistake": "Accepting the easiest metric because it is available.", "mentalModel": "Measure close to the goal."}, "invest": {"call": {"kind": "theCall", "situation": "A learning app's pitch shows time in the app up sharply after reinforcement learning tuning.", "prompt": "What do you ask?", "options": ["Nothing, since engagement is the goal", "Whether learning outcomes rose too", "How much higher time in the app can go"], "correctIndex": 1, "consequences": ["For a learning app, learning is the goal.", "If learning did not rise, the app optimized a proxy.", "More time can mean the proxy is being gamed harder."], "explanation": "An AI product tuned to an easy metric can look great and still fail customers."}, "proReasoning": "Investors ask what the tuning rewarded and whether the real outcome moved. Engagement alone is not learning.", "commonMistake": "Treating engagement as proof of value.", "mentalModel": "Ask if the real outcome moved."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder, choosing the reward before your team builds anything.", "prompt": "What's the first step?", "options": ["Pick whichever metric is the easiest to log", "Start building now and choose a metric later", "Write the goal and test the metric against it"], "correctIndex": 2, "consequences": ["Easy to log is how proxies sneak in.", "The reward shapes what you build, so choose it first.", "If goal and metric can drift apart, you find out before building."], "explanation": "Write the real goal and the metric side by side. If they can drift apart, test that first."}, "proReasoning": "Founders set the reward before the code, because the reward decides what the model becomes.", "commonMistake": "Letting whatever is easy to measure become the goal.", "mentalModel": "Goal first, then the metric."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an AI rewarded for minutes in a learning app might not teach well.", "prompt": "What's the answer?", "options": ["It would learn to keep people in, not to teach", "Minutes are impossible for an AI to measure", "Learning apps cannot use AI at all"], "correctIndex": 0, "consequences": ["Like the boat circling for points, it chases what is scored.", "Minutes are easy to measure, which is the problem.", "They can; the question is what to reward."], "explanation": "A model optimizes what you measure, not what you meant."}, "proReasoning": "Ask what an AI is scored on. That tells you what it will get good at.", "commonMistake": "Assuming the AI knows what you really meant.", "mentalModel": "It chases the score."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e29616ee-3608-56fb-8771-dd31918d9dd6$ml$::uuid, $ml$ai$ml$, 7, 1, $ml${"id": "ai-d7-c1", "title": "Writing in parallel", "lessonTitle": "Three designs behind modern AI", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Inception raised $50 million to build diffusion language models. Instead of writing one token at a time, they refine a whole answer at once, and were benchmarked at over 1,000 tokens per second.", "kicker": "Apply day 7: can writing in parallel scale like reading did?", "fullText": "Most chatbots, including GPT-5 and Gemini, are autoregressive: they predict one word or word fragment at a time, in order. Inception, led by Stanford professor Stefano Ermon, builds diffusion models for text and code instead. They refine the whole output in steps until it reaches the target, which lets them run many operations at once.\n\nMenlo Ventures led the $50 million seed round, with Microsoft's M12, Nvidia's NVentures, Snowflake and Databricks taking part, plus Andrew Ng and Andrej Karpathy. Ermon credits the parallel design for benchmarks of over 1,000 tokens per second.\n\nThis is the day 7 pattern again. The Transformer won by dropping recurrence so it could process a sequence in parallel. Diffusion is a bet that writing in parallel can scale too.", "sources": [{"url": "https://www.techcrunch.com/2025/11/06/inception-raises-50-million-to-build-diffusion-models-for-code-and-text/", "label": "TechCrunch, Inception raises $50 million to build diffusion models, Nov 2025"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which way of writing does each one describe?", "buckets": ["One token at a time", "Whole answer at once"], "items": [{"text": "How GPT-5 and Gemini generate text", "bucket": 0}, {"text": "Each word predicted after the one before", "bucket": 0}, {"text": "Refines the full output in steps", "bucket": 1}, {"text": "Benchmarked at over 1,000 tokens per second", "bucket": 1}, {"text": "Inception's Mercury models", "bucket": 1}], "explanation": "Autoregressive models write in order. Diffusion models work on the whole answer at once, which runs in parallel."}, "numbers": {"kind": "numberSense", "prompt": "At 1,000 tokens per second, how many seconds would a 6,000-token code file take to write?", "min": 0, "max": 30, "value": 6, "unit": "seconds", "explanation": "Six seconds. Speed like that is why parallel generation appeals for long code."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Inception. They ask how their models differ from GPT-5.", "prompt": "What's the best answer?", "options": ["They use image networks built for photos", "They are RNNs that read one step at a time", "They refine the whole output at once"], "correctIndex": 2, "consequences": ["Convolutional networks were the 2012 image breakthrough, not this.", "RNNs are the sequential design the Transformer replaced.", "Right: that parallel step is the whole bet."], "explanation": "Naming the design under the hood shows you know what makes the product fast."}, "proReasoning": "Say what the architecture is and why it matters. \"Diffusion writes in parallel, so it is faster\" is a complete answer.", "commonMistake": "Calling every new model \"a better Transformer\" without naming the change.", "mentalModel": "Name the architecture."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims a new design that writes far faster than standard chatbots.", "prompt": "What's the key question for an investor?", "options": ["Whether it cuts cost at the same quality", "Whether its seed round was large enough", "Whether it uses the newest GPUs"], "correctIndex": 0, "consequences": ["Architecture shifts matter when they change what AI costs to build or run.", "Round size says little about whether the design wins.", "Hardware alone does not make a new design better."], "explanation": "A 2017 paper changed which models won. Watch for the next design that changes what AI costs."}, "proReasoning": "Investors watch for architecture shifts that change costs. Speed matters if quality holds.", "commonMistake": "Judging a new design by who funded it rather than what it changes.", "mentalModel": "Watch designs that change the cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a coding tool. Users complain about waiting for long completions.", "prompt": "What's a sound move?", "options": ["Rebuild the product around image networks", "Test a parallel model where speed matters most", "Assume only one-token-at-a-time models work"], "correctIndex": 1, "consequences": ["Image networks do not write code.", "If quality holds, faster generation fixes your users' pain.", "Diffusion models already write code at over 1,000 tokens per second."], "explanation": "The design shapes speed and cost. Test new designs where they address your users' biggest pain."}, "proReasoning": "Founders test new architectures against a real user pain, here waiting time, before switching.", "commonMistake": "Ignoring a design shift because the current one is familiar.", "mentalModel": "Test the design against the pain."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chatbot's answer appears word by word.", "prompt": "What's the explanation?", "options": ["The app slows it down just for effect", "Your internet sends one word at a time", "Most models write one token at a time"], "correctIndex": 2, "consequences": ["The words appear as the model produces them.", "The network is not the reason; the model is.", "Each word is predicted after the one before, so it streams in."], "explanation": "Autoregressive models predict in order. Diffusion models try to write the whole answer at once."}, "proReasoning": "Watch how a tool behaves and ask what design causes it. Word by word means writing in order.", "commonMistake": "Assuming the typing effect is just decoration.", "mentalModel": "Behavior hints at the design."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$27678f05-a702-507a-b7f2-94b5d6cc206d$ml$::uuid, $ml$ai$ml$, 7, 2, $ml${"id": "ai-d7-c2", "title": "From two GPUs to a chokepoint", "lessonTitle": "Three designs behind modern AI", "slot": 2, "type": "connect", "brief": {"headline": "In 2012, the network that won a top image contest trained on two GPUs for five to six days. In fiscal 2026, NVIDIA's data center chips brought in $193.7 billion.", "kicker": "Connect day 3 and day 7: parallel designs made GPUs the scarce input.", "fullText": "On day 7 you met the 2012 breakthrough: a convolutional network with 60 million parameters, trained on two GTX 580 GPUs, won with a 15.3% error rate against 26.2% for the runner-up. Then came the 2017 Transformer, which dropped recurrence so it could process a sequence in parallel. Parallel work suits GPUs.\n\nOn day 3 you saw who holds power in AI: whoever controls the scarcest input. Each design that ran better in parallel made those chips more valuable. By fiscal 2026, NVIDIA's data center business brought in $193.7 billion, at gross margins above 70%.", "sources": [{"url": "https://courses.cs.duke.edu/fall16/compsci527/papers/Krizhevsky%20et%20al%20DNN%20ImageNet%202012.pdf", "label": "Krizhevsky, Sutskever and Hinton, ImageNet classification with deep CNNs, 2012"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how parallel designs fed the chip boom.", "steps": ["2012: a CNN wins the image contest on two GPUs", "2017: the Transformer drops recurrence", "Models process whole sequences in parallel", "Parallel work suits GPUs, so demand soars", "NVIDIA's data centers bring in $193.7 billion"], "explanation": "Designs that run in parallel scale on GPUs. That turned GPUs into the scarce input."}, "numbers": {"kind": "numberSense", "prompt": "About how many million parameters did the 2012 winning network have?", "min": 0, "max": 200, "value": 60, "unit": "M", "explanation": "About 60 million, trained on two GPUs. Frontier models today use vastly more compute."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chip company. They ask why AI demand favors GPUs.", "prompt": "What's the sharpest answer?", "options": ["Its designs run in parallel, which suits GPUs", "GPUs are cheaper than any other kind of chip", "AI models need to draw graphics on screen"], "correctIndex": 0, "consequences": ["That link between design and hardware is what they want to hear.", "Margins above 70% say GPUs are not cheap.", "The graphics origin matters less than the parallel math."], "explanation": "The Transformer runs in parallel, and parallel work suits GPUs. Demand followed."}, "proReasoning": "Connect the architecture to the hardware. It shows you see why one chip became the chokepoint.", "commonMistake": "Explaining GPU demand by price or graphics rather than by parallel design.", "mentalModel": "Design decides the chip."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a GPU maker and follow AI research news.", "prompt": "What kind of news should you watch most?", "options": ["A new nickname for the Transformer", "Designs that need less parallel compute", "Another record on an old image contest"], "correctIndex": 1, "consequences": ["Names do not change what chips a model needs.", "A shift in design could change which chips are scarce.", "Old benchmarks say little about chip demand now."], "explanation": "Parallel designs made GPUs the chokepoint. A design shift is what could change that."}, "proReasoning": "Investors in a chokepoint ask what could end the scarcity. An architecture shift is one answer.", "commonMistake": "Assuming today's design will last forever.", "mentalModel": "Watch what could end the scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your model could be an RNN or a Transformer. You rent GPUs by the hour.", "prompt": "Which suits your hardware better?", "options": ["The RNN, which reads one step at a time", "Either, since design does not affect the bill", "The Transformer, which runs in parallel"], "correctIndex": 2, "consequences": ["RNNs are hard to run in parallel, so GPU hours stretch.", "Your architecture shapes your compute costs.", "Parallel work keeps rented GPUs busy and training fast."], "explanation": "Transformers process sequences in parallel, which suits GPUs. That shapes your bill."}, "proReasoning": "Founders pick designs that match the hardware they pay for. Idle parallel chips are wasted money.", "commonMistake": "Choosing an architecture without thinking about the hardware bill.", "mentalModel": "Match the design to the chip."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a graphics chip company ended up at the center of AI.", "prompt": "What's the best answer?", "options": ["AI's parallel math suits its chips", "Chatbots draw a picture for every answer", "It owns the AI models people use"], "correctIndex": 0, "consequences": ["The 2012 breakthrough already trained on two GPUs.", "Most AI answers are text, not pictures.", "Its $193.7 billion came from data center chips."], "explanation": "GPUs do parallel work well, and modern AI designs are built to run in parallel."}, "proReasoning": "A tool built for one job can win another if the math matches. GPUs fit AI's parallel math.", "commonMistake": "Thinking AI chips had to be invented from scratch.", "mentalModel": "Same math, new market."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9347749c-6748-5422-b08a-b9e29bf659d3$ml$::uuid, $ml$ai$ml$, 7, 3, $ml${"id": "ai-d7-c3", "title": "Reading long contracts", "lessonTitle": "Three designs behind modern AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a small team building a tool that reads long contracts. You must pick a design: a recurrent network that reads one step at a time, or a Transformer built on attention.", "kicker": "Decide which design fits long documents on rented GPUs.", "fullText": "Recurrent networks, or RNNs, read a sequence one step at a time, so they are hard to run in parallel. In 2017, Google researchers introduced the Transformer, built on attention. It dropped recurrence so it could process a whole sequence in parallel.\n\nConvolutional networks powered the 2012 image breakthrough: a CNN won with a 15.3% error rate against 26.2% for the runner-up, after five to six days of training on two GPUs. In deep learning, designs that run in parallel are the ones that scale.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://courses.cs.duke.edu/fall16/compsci527/papers/Krizhevsky%20et%20al%20DNN%20ImageNet%202012.pdf", "label": "Krizhevsky, Sutskever and Hinton, ImageNet classification with deep CNNs, 2012"}]}, "evidence": {"kind": "faceOff", "prompt": "For reading long documents fast on GPUs, which design fits better?", "left": {"name": "Recurrent network (RNN)", "note": "Reads one step at a time"}, "right": {"name": "Transformer", "note": "Built on attention, runs in parallel"}, "correctIndex": 1, "explanation": "The Transformer processes a sequence in parallel, which suits GPUs. RNNs are hard to parallelize."}, "numbers": {"kind": "numberSense", "prompt": "The 2012 CNN had a 15.3% error rate; the runner-up had 26.2%. How many points better was it?", "min": 0, "max": 30, "value": 10.9, "unit": "points", "explanation": "About 10.9 points, a huge margin. A design shift can open a gap that size."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to join the team. They ask which design you'd pick and why.", "prompt": "What's your answer?", "options": ["CNN, since it won the 2012 image contest", "Transformer, since it processes text in parallel", "RNN, since reading in order is always better"], "correctIndex": 1, "consequences": ["The 2012 win was for images, not contracts.", "Parallel processing suits GPUs and long documents.", "Reading in order is what makes RNNs slow to train."], "explanation": "Pick the design and give the reason. Parallel processing is why Transformers scale."}, "proReasoning": "Name the architecture and the trade it makes. Interviewers want the why, not just the name.", "commonMistake": "Picking a design for its fame rather than its fit.", "mentalModel": "Name it, then say why it fits."}, "invest": {"call": {"kind": "theCall", "situation": "Two contract-reading startups pitch you. One is built on RNNs, the other on Transformers.", "prompt": "Which design should scale better?", "options": ["The RNN, since older designs are safer", "Neither, since design does not affect costs", "The Transformer, which runs in parallel"], "correctIndex": 2, "consequences": ["Older is not safer when it cannot use the hardware well.", "The design shapes how much compute each document needs.", "Parallel designs are the ones that scale on GPUs."], "explanation": "Designs that run in parallel are the ones that scale. That shows up in cost and speed."}, "proReasoning": "Investors ask what a product runs on, because the design shapes the cost curve.", "commonMistake": "Treating the architecture as a detail for engineers.", "mentalModel": "The design shapes the cost curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your contracts run hundreds of pages, and you rent GPUs by the hour.", "prompt": "How do you choose?", "options": ["Pick the design that uses GPUs in parallel", "Pick the design that reads strictly in order", "Pick the design built for photos"], "correctIndex": 0, "consequences": ["That keeps your rented GPUs busy and your bill down.", "Sequential reading wastes the parallel hardware you pay for.", "CNNs suited images; your input is text."], "explanation": "Your architecture choice shapes your compute bill. Parallel designs suit GPUs."}, "proReasoning": "Founders choose the design that fits both the data and the hardware bill.", "commonMistake": "Choosing by habit instead of by fit.", "mentalModel": "Fit the data and the bill."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a \"Transformer\" is in AI.", "prompt": "What's the best short answer?", "options": ["A program that converts file types", "A 2017 design built on attention", "A robot that changes its shape"], "correctIndex": 1, "consequences": ["It is a neural network design, not a file tool.", "Google researchers introduced it, and it runs in parallel.", "That is the toy, not the AI design."], "explanation": "The Transformer is the design behind most modern language models. It reads a whole sequence in parallel."}, "proReasoning": "Explain a design by what it does differently. Transformers read in parallel; RNNs read in order.", "commonMistake": "Getting lost in the name instead of the idea.", "mentalModel": "Explain what it does differently."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ffa6e084-e4f0-5fa1-8137-6d5c732e232f$ml$::uuid, $ml$ai$ml$, 8, 1, $ml${"id": "ai-d8-c1", "title": "The $5.6 million headline", "lessonTitle": "From $900 to $191 million", "slot": 1, "type": "apply", "brief": {"headline": "In December 2024, DeepSeek said its V3 model's training used 2.788 million H800 GPU hours, about $5.6 million. On January 27, 2025, NVIDIA lost over $589 billion in market value in one day.", "kicker": "Apply day 8: what does a training cost figure actually cover?", "fullText": "DeepSeek-V3 has 671 billion parameters, with 37 billion active for each token, and trained on 14.8 trillion tokens on 2,048 H800 GPUs. Its paper priced the run at $5.576 million, assuming $2 per GPU hour. It said the figure covered only the official training, excluding prior research and ablation experiments on architectures, algorithms and data.\n\nAs DeepSeek's models drew attention, NVIDIA's stock fell about 17% on January 27, 2025, wiping out more than $589 billion of market value, the largest one-day loss for any company. Investors wondered whether frontier training had suddenly become cheap.\n\nStanford's estimates, like GPT-4's $78 million, also count training compute. A figure like that is real, but it is not the full cost of building a lab that can produce the model.", "sources": [{"url": "https://ar5iv.labs.arxiv.org/html/2412.19437", "label": "DeepSeek-AI, DeepSeek-V3 technical report, Dec 2024"}, {"url": "https://simonwillison.net/2024/Dec/26/deepseek-v3", "label": "Simon Willison, DeepSeek v3, Dec 2024"}, {"url": "https://www.tomshardware.com/tech-industry/artificial-intelligence/nvidia-loses-usd589-billion-in-market-cap-broad-stock-plunge-triggered-by-deepseek-ai-release", "label": "Tom's Hardware, Nvidia loses $589 billion in market cap, Jan 2025"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about DeepSeek-V3's cost figure. Tap it.", "statements": ["It assumed $2 for each H800 GPU hour.", "It included all prior research and experiments.", "Training ran on 2,048 H800 GPUs."], "fakeIndex": 1, "explanation": "The paper said the figure excluded prior research and ablation experiments. It covered the official training run."}, "numbers": {"kind": "numberSense", "prompt": "Llama 3.1 405B used about 30.8 million GPU hours; DeepSeek-V3 about 2.8 million. Roughly how many times more?", "min": 0, "max": 30, "value": 11, "unit": "x", "explanation": "About 11 times. Efficiency was real, even if the headline cost left a lot out."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview whether DeepSeek proved frontier AI is now cheap to build.", "prompt": "What's the best answer?", "options": ["It cut run costs, but the figure omits research", "Yes, any lab can now train one for $6 million", "No, the number was simply invented by DeepSeek"], "correctIndex": 0, "consequences": ["That separates a real efficiency gain from the full bill.", "The paper itself said prior research was excluded.", "The paper detailed its GPU hours; the question is scope."], "explanation": "Know what a cost estimate counts. A final run is not the whole cost of a frontier model."}, "proReasoning": "Quote the number and its scope. \"About $5.6 million for the final run, excluding research\" shows care.", "commonMistake": "Repeating a headline cost without asking what it covers.", "mentalModel": "Every cost figure has a scope."}, "invest": {"call": {"kind": "theCall", "situation": "NVIDIA falls 17% in a day on fears that frontier training just got cheap.", "prompt": "What's the sound way to read the news?", "options": ["Ignore it, since efficiency never matters", "Check what the cost figure covers first", "Sell all chip stocks, since demand is over"], "correctIndex": 1, "consequences": ["An 11 times efficiency claim is worth understanding.", "The figure excluded research, so the full cost was higher.", "One cost figure does not end demand for compute."], "explanation": "Compute spending drives the market. Before repricing it, check what a cheaper headline really counts."}, "proReasoning": "Investors read the footnote before the headline. Scope can turn a shock into a smaller story.", "commonMistake": "Trading on a cost number without reading what it includes.", "mentalModel": "Read the footnote first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You read DeepSeek's paper and want to train your own frontier model for about $6 million.", "prompt": "How should you budget?", "options": ["Raise $6 million and plan one run", "Assume cheaper chips mean little budget", "Add research and failed runs on top"], "correctIndex": 2, "consequences": ["One run with no experiments before it is not how it was done.", "It still took 2,048 GPUs for about two months.", "The $5.6 million covered only the final, successful run."], "explanation": "Training cost is a barrier at the frontier. Even efficient runs sit on top of research spending."}, "proReasoning": "Founders budget for the experiments that come before the final run. That is where much of the money goes.", "commonMistake": "Budgeting for the headline run alone.", "mentalModel": "Budget for the experiments too."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says a Chinese startup built a top AI model for only $6 million.", "prompt": "What's the fairer version?", "options": ["That covered its final training run only", "Yes, that was the full cost of everything", "No, it actually cost $6 billion"], "correctIndex": 0, "consequences": ["Research and experiments before the run were left out.", "The paper itself said research costs were excluded.", "No source puts the cost at $6 billion."], "explanation": "The number was real but narrow: one training run, priced at rented GPU rates."}, "proReasoning": "When a number sounds too good, ask what it leaves out.", "commonMistake": "Taking a narrow number as the whole story.", "mentalModel": "Ask what the number leaves out."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$00a224e2-d29f-5d2b-b781-e4f2c7e95dee$ml$::uuid, $ml$ai$ml$, 8, 2, $ml${"id": "ai-d8-c2", "title": "When compounding meets a budget", "lessonTitle": "From $900 to $191 million", "slot": 2, "type": "connect", "brief": {"headline": "The original 2017 Transformer cost about $900 to train. GPT-4 cost an estimated $78 million, and Gemini Ultra about $191 million, as training compute grew 4 to 5 times a year.", "kicker": "Connect day 4 and day 8: a compounding curve becomes a price tag.", "fullText": "On day 4 you saw training compute for frontier models grow 4 to 5 times every year, doubling roughly every five months. On day 8 you saw what that means in dollars: about $900 for the original Transformer in 2017, an estimated $78 million for GPT-4, and $191 million worth of compute for Gemini Ultra.\n\nA cost that multiplies each year becomes a barrier to entry. Only a few firms can keep paying for the next step.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A $100 million frontier run uses compute that grows 4 times a year. At the same price, what might next year's run cost?", "options": ["About $400 million", "About $104 million", "About $200 million"], "correctIndex": 0, "explanation": "Four times the compute at the same price is four times the bill. That is how $900 became $191 million."}, "numbers": {"kind": "numberSense", "prompt": "From about $900 to about $191 million: roughly how many times more, in thousands?", "min": 0, "max": 500, "value": 212, "unit": "K", "explanation": "About 212,000 times more in roughly six years. Compounding turned a hobby budget into nine figures."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why only a few firms train frontier models.", "prompt": "What's the best answer?", "options": ["Governments limit who may train them", "Costs multiply yearly, into nine figures", "The ideas are secret and locked away"], "correctIndex": 1, "consequences": ["Cost, not permission, is the main barrier.", "GPT-4 alone used an estimated $78 million of compute.", "The Transformer paper was published openly."], "explanation": "Training cost has become a barrier to entry at the frontier."}, "proReasoning": "Explain market structure with cost. \"$78 million for GPT-4\" explains why the frontier has few players.", "commonMistake": "Blaming secrecy when the barrier is money.", "mentalModel": "Cost shapes who can compete."}, "invest": {"call": {"kind": "theCall", "situation": "Training costs rose from about $900 to an estimated $191 million.", "prompt": "Where does most of that money land?", "options": ["With the authors of research papers", "With the apps built on top", "With chip and cloud providers"], "correctIndex": 2, "consequences": ["Papers are free to read; authors are not paid per run.", "Apps pay model makers; training money flows down, not up.", "Training budgets pay for compute, which means chips and cloud."], "explanation": "Most training spending flows to chips and cloud. That is why compute suppliers grew so fast."}, "proReasoning": "Investors follow training budgets to whoever supplies compute. Rising costs are their revenue.", "commonMistake": "Thinking training spending enriches the model makers directly.", "mentalModel": "Training money flows to compute."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build an AI product, and frontier training costs nine figures.", "prompt": "Where do you compete?", "options": ["On top of a model someone else trained", "By training your own frontier model first", "By waiting for training to cost $900 again"], "correctIndex": 0, "consequences": ["Someone else already paid for the training.", "You would need tens of millions before your first user.", "Frontier costs are rising, not falling back."], "explanation": "Many openings sit on top of models others already paid to train."}, "proReasoning": "Founders build where the expensive part is already paid for.", "commonMistake": "Trying to cross a nine-figure barrier on a seed budget.", "mentalModel": "Build where training is paid for."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI training got so expensive so fast.", "prompt": "What's the main reason?", "options": ["Engineers kept raising their salaries", "The compute used grew 4 to 5 times a year", "Chip prices rose about 200,000-fold"], "correctIndex": 1, "consequences": ["These estimates count compute, not salaries.", "More compute each year, compounded, became a huge bill.", "The growth came from using far more compute, not pricier chips."], "explanation": "Compounding growth in compute turned $900 into $191 million in a few years."}, "proReasoning": "Big cost jumps often come from compounding volume. Count how much more is used, not just the price.", "commonMistake": "Blaming prices when volume did the work.", "mentalModel": "Volume compounds into cost."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$239db8bb-31fa-5545-932e-bd34888c0fae$ml$::uuid, $ml$ai$ml$, 8, 3, $ml${"id": "ai-d8-c3", "title": "A $20 million rival to GPT-4", "lessonTitle": "From $900 to $191 million", "slot": 3, "type": "decide", "brief": {"headline": "You run a small venture fund. A team asks for $20 million to train a model from scratch to rival GPT-4.", "kicker": "Decide whether the budget fits the frontier.", "fullText": "Stanford's 2024 AI Index estimated the compute cost of training major models. The original 2017 Transformer cost about $900. GPT-4 cost an estimated $78 million, and Gemini Ultra about $191 million worth of compute.\n\nThese estimates count only the compute used to train a model. In AI, training cost has become a barrier to entry at the frontier, and many openings sit on top of models someone else already trained.", "sources": [{"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does $20 million cover each one?", "buckets": ["Fits $20 million", "Doesn't fit"], "items": [{"text": "GPT-4's estimated $78 million of compute", "bucket": 1}, {"text": "Gemini Ultra's $191 million of compute", "bucket": 1}, {"text": "Training the 2017 Transformer, about $900", "bucket": 0}, {"text": "A narrow product built on an existing model", "bucket": 0}], "explanation": "The frontier runs cost several times the budget. A narrow product on an existing model fits easily."}, "numbers": {"kind": "numberSense", "prompt": "$20 million covers about what share of GPT-4's estimated $78 million compute bill?", "min": 0, "max": 100, "value": 26, "unit": "%", "explanation": "About a quarter, and that is compute alone, before staff or experiments."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The team's lead asks you to join as its first machine learning engineer.", "prompt": "What do you check first?", "options": ["Whether the office has its own GPUs", "Whether the model has a catchy name", "Whether $20 million can cover the compute"], "correctIndex": 2, "consequences": ["Owning a few GPUs is not frontier-scale compute.", "Names do not train models.", "GPT-4 alone used an estimated $78 million of compute."], "explanation": "Know what a model costs before betting your career on building one."}, "proReasoning": "Before joining, check that the plan can be paid for. Compute is the first line to test.", "commonMistake": "Joining on ambition without checking the math.", "mentalModel": "Check the compute math first."}, "invest": {"call": {"kind": "theCall", "situation": "You are deciding on the $20 million request.", "prompt": "What's the key gap in the plan?", "options": ["GPT-4's compute alone cost about $78 million", "Their team is far too small to matter", "None, since $20 million is plenty for it"], "correctIndex": 0, "consequences": ["The budget covers about a quarter of that.", "Team size matters less than the compute bill.", "It covers about a quarter of the compute."], "explanation": "Compute spending sets the bar. A frontier rival needs several times this budget."}, "proReasoning": "Investors compare the ask with what the goal costs. A frontier model on a fraction of the bill is a red flag.", "commonMistake": "Funding an ambition that the budget cannot reach.", "mentalModel": "Compare the ask with the bill."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The fund says $20 million won't train a GPT-4 rival.", "prompt": "What's your best next move?", "options": ["Ask for $20 million more and try anyway", "Build a narrow product on an existing model", "Train a smaller copy and call it a rival"], "correctIndex": 1, "consequences": ["At $40 million you would still be far short.", "Someone else already paid for the expensive training.", "Calling it a rival does not make it one."], "explanation": "Build where training is already paid for. Compete on the use, not the base model."}, "proReasoning": "Founders turn a cost barrier into a choice of where to compete. The use case is open; the frontier is not.", "commonMistake": "Doubling down on a race the budget cannot win.", "mentalModel": "Compete on the use, not the base."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why more startups don't build their own ChatGPT.", "prompt": "What's the main reason?", "options": ["The code is illegal for startups to write", "Only big companies are allowed to use GPUs", "Training one costs tens of millions or more"], "correctIndex": 2, "consequences": ["The methods are published openly.", "Anyone can rent GPUs; the volume is what costs.", "GPT-4 cost an estimated $78 million in compute."], "explanation": "The barrier is the compute bill, which runs to tens or hundreds of millions."}, "proReasoning": "When few players compete, look at the entry cost. In frontier AI, it is compute.", "commonMistake": "Assuming the barrier is secret knowledge.", "mentalModel": "Look at the entry cost."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$6aef4336-dbae-5e6d-8d2b-0d68e2eb9277$ml$::uuid, $ml$ai$ml$, 9, 1, $ml${"id": "ai-d9-c1", "title": "The $2.7 billion rehire", "lessonTitle": "Inventors versus shippers", "slot": 1, "type": "apply", "brief": {"headline": "Noam Shazeer co-wrote the 2017 Transformer paper and left Google in 2021. In 2024, Google reportedly paid $2.7 billion to bring him back. In June 2026, he left again, for OpenAI.", "kicker": "Apply day 9: ideas travel with the people who have them.", "fullText": "Shazeer joined Google in 2000. He left in 2021 after Google declined to release a chatbot he had built, and co-founded Character.AI, serving as its CEO.\n\nIn August 2024, Google struck a licensing deal with Character.AI that brought Shazeer and several key researchers back. The Wall Street Journal reported Google paid about $2.7 billion. He became a vice president of engineering and co-lead of Gemini.\n\nOn June 17, 2026, Shazeer said he was leaving Google to join OpenAI, the maker of ChatGPT. Google told Reuters it was grateful for his contributions.\n\nThe day 9 pattern played out twice. The people carry the ideas, and companies that ship keep pulling them in.", "sources": [{"url": "https://analyticsindiamag.com/ai-news/openai-poaches-transformer-pioneer-noam-shazeer-from-google", "label": "Analytics India Magazine, OpenAI hires Noam Shazeer from Google, Jun 2026"}, {"url": "https://www.pymnts.com/artificial-intelligence-2/2024/google-reportedly-spent-2-7-billion-to-rehire-character-ai-founder/", "label": "PYMNTS, Google reportedly spent $2.7 billion to rehire Character.AI founder, Sep 2024"}, {"url": "https://www.thestar.com.my/tech/tech-news/2026/06/18/google-gemini-co-lead-noam-shazeer-to-join-ipo-bound-openai", "label": "Reuters via The Star, Gemini co-lead Noam Shazeer to join OpenAI, Jun 2026"}, {"url": "https://9to5google.com/2026/06/17/geminis-co-lead-is-leaving-google-to-join-openai/", "label": "9to5Google, Gemini's co-lead is leaving Google to join OpenAI, Jun 2026"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Shazeer's moves in order.", "steps": ["Co-writes the Transformer paper at Google", "Leaves after Google holds back his chatbot", "Co-founds Character.AI", "Google pays about $2.7 billion to bring him back", "Leaves Google again to join OpenAI"], "explanation": "An inventor left, was bought back, and left again. Each move followed where ideas could ship."}, "numbers": {"kind": "numberSense", "prompt": "Google reportedly paid about how many billion dollars in the 2024 deal?", "min": 0, "max": 10, "value": 2.7, "unit": "B", "explanation": "About $2.7 billion, largely to bring back one researcher and his team."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're choosing between two AI labs. One keeps losing senior researchers to rivals.", "prompt": "What does that tell you?", "options": ["It's stronger, since rivals want its people", "Power may be shifting to where they go", "Nothing, since people leave every company"], "correctIndex": 1, "consequences": ["Losing people is a cost, even if it flatters the lab.", "In AI, where talent goes, power tends to follow.", "A pattern of senior exits is a signal, not noise."], "explanation": "Ask which teams people leave to join, and why. It shows where the work that matters is happening."}, "proReasoning": "Track where senior people go. In AI, the flow of talent is an early map of power.", "commonMistake": "Treating departures as random churn.", "mentalModel": "Follow the talent."}, "invest": {"call": {"kind": "theCall", "situation": "Google paid about $2.7 billion to rehire one researcher. Under two years later he left for a rival.", "prompt": "What's the investor lesson?", "options": ["Licensing deals lock talent in for good", "Researchers matter less than chips do", "Key talent is an asset that can walk out"], "correctIndex": 2, "consequences": ["He left within two years of the deal.", "Google paid billions for a person, not a chip.", "A big payment bought time, not permanence."], "explanation": "In AI, value sits partly in people. They can leave, and they take know-how with them."}, "proReasoning": "Investors count people as a risk on the balance sheet. Paying for talent does not keep it.", "commonMistake": "Assuming a deal locks in the people it was made for.", "mentalModel": "People can walk; price that in."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shazeer left when Google held back his chatbot. You see a big lab sitting on a useful idea.", "prompt": "What's the founder's move?", "options": ["Ship a product users can try now", "Wait until the lab releases it", "Publish a paper about the idea"], "correctIndex": 0, "consequences": ["Users waiting on a slow incumbent are your opening.", "The lab may never release it, and users keep waiting.", "A paper spreads the idea; it does not reach users."], "explanation": "Big labs can sit on breakthroughs. Users who want them feel that delay, and that is an opening."}, "proReasoning": "Founders look for ideas big companies hold back. Shipping first is the advantage.", "commonMistake": "Assuming the incumbent will always ship its best ideas.", "mentalModel": "Ship what others hold back."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google would pay billions to rehire someone who used to work there.", "prompt": "What's the best explanation?", "options": ["Google buys every startup it sees", "His know-how left with him", "It was a fine for quitting"], "correctIndex": 1, "consequences": ["Google chose this deal to rehire specific people.", "Ideas travel with the people who have them.", "Nobody fines people for leaving; Google paid to get him back."], "explanation": "A company can keep the paper, but the expertise walks out the door with the person."}, "proReasoning": "In research-heavy fields, people are the product. Companies pay to get them back.", "commonMistake": "Thinking a company owns everything its people know.", "mentalModel": "Know-how walks with people."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$097b3fb3-10df-52c6-bc86-62bdf01635da$ml$::uuid, $ml$ai$ml$, 9, 2, $ml${"id": "ai-d9-c2", "title": "Invented here, shipped there", "lessonTitle": "Inventors versus shippers", "slot": 2, "type": "connect", "brief": {"headline": "Google researchers introduced the Transformer in 2017, and all eight authors later left Google. OpenAI's ChatGPT, built on its GPT Transformers, reached about 100 million monthly users two months after launch.", "kicker": "Connect day 7 and day 9: the design spread; a shipper won the users.", "fullText": "On day 7 you met the Transformer: a 2017 design built on attention that dropped recurrence so it could process sequences in parallel. On day 9 you saw what happened to it. The paper, Attention Is All You Need, has been cited more than 250,000 times, and all eight authors left Google to join other companies or found startups.\n\nThe idea was published openly, so anyone could build on it. OpenAI's GPT series of Transformers became state of the art in generating text, and ChatGPT reached about 100 million monthly users in January 2023, two months after launch. The inventor did not capture the first wave of users. The shipper did.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}]}, "evidence": {"kind": "sortSignal", "prompt": "Inventor or shipper: which company does each describe?", "buckets": ["Google", "OpenAI"], "items": [{"text": "Published Attention Is All You Need", "bucket": 0}, {"text": "Saw all eight authors leave", "bucket": 0}, {"text": "Built the GPT series of Transformers", "bucket": 1}, {"text": "Launched ChatGPT in late 2022", "bucket": 1}, {"text": "Reached 100 million users in two months", "bucket": 1}], "explanation": "Google invented and published. OpenAI built on the open idea and shipped it to users."}, "numbers": {"kind": "numberSense", "prompt": "The Transformer paper has been cited more than how many thousand times?", "min": 0, "max": 600, "value": 250, "unit": "K", "explanation": "More than 250,000 times. An open idea spreads widely, and anyone can build on it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked who benefited most from the Transformer at first.", "prompt": "What's the best answer?", "options": ["Only Google, which owned the idea", "Nobody, since the paper was free to read", "Those who shipped products on it, like OpenAI"], "correctIndex": 2, "consequences": ["Google published it openly, and its authors left.", "Free ideas still create value for whoever ships them.", "ChatGPT reached 100 million users while the inventor waited."], "explanation": "Invention spreads. Value goes to whoever turns it into a product people use."}, "proReasoning": "Separate who invented from who captured value. Interviewers like candidates who see the gap.", "commonMistake": "Assuming the inventor always wins.", "mentalModel": "Invention spreads; shipping captures."}, "invest": {"call": {"kind": "theCall", "situation": "One AI company publishes top papers. Another has 100 million users.", "prompt": "Which edge is harder to copy?", "options": ["The user base, since papers are public", "The papers, since ideas cannot be copied", "Neither, since both are easy to copy"], "correctIndex": 0, "consequences": ["Anyone can read a paper; users must be won one by one.", "Published ideas are the easiest thing to copy.", "Reaching 100 million users took a shipped product."], "explanation": "Distribution beats invention. Watch who reaches users."}, "proReasoning": "Investors ask which advantage a rival cannot simply read. Users are harder to copy than ideas.", "commonMistake": "Valuing research output over reach.", "mentalModel": "Distribution beats invention."}, "build_startup": {"call": {"kind": "theCall", "situation": "A big lab publishes a powerful new method openly.", "prompt": "What's your move as a founder?", "options": ["Ignore it, since published ideas lose value", "Build a product on it before the lab does", "Wait for the lab to ship it first"], "correctIndex": 1, "consequences": ["Published ideas are the raw material for products.", "OpenAI did that with the Transformer and won the users.", "The inventor may be slow, as Google was."], "explanation": "Open research is free raw material. The race is to ship it."}, "proReasoning": "Founders read papers as a parts catalog. The win goes to whoever ships first.", "commonMistake": "Waiting for the inventor to move.", "mentalModel": "Papers are parts; ship the product."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ChatGPT came from OpenAI if Google invented the Transformer.", "prompt": "What's the answer?", "options": ["OpenAI bought the Transformer from Google", "Google gave ChatGPT to OpenAI", "OpenAI built and shipped on the open idea"], "correctIndex": 2, "consequences": ["No purchase was needed; the paper was published.", "Google did not build ChatGPT.", "The paper was public, so anyone could use the idea."], "explanation": "Google published the idea openly. OpenAI built a product on it and reached users first."}, "proReasoning": "Inventing something and selling it are different skills. Often different companies do each.", "commonMistake": "Assuming the inventor and the seller are the same.", "mentalModel": "Inventor and shipper can differ."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$5b5a99a0-8269-5b41-933d-c229f7125729$ml$::uuid, $ml$ai$ml$, 9, 3, $ml${"id": "ai-d9-c3", "title": "Keep the idea, lose the team?", "lessonTitle": "Inventors versus shippers", "slot": 3, "type": "decide", "brief": {"headline": "You lead an AI research group at a large company. Your team has a strong new method, and two senior researchers say they'll leave to start a company if it stays in the lab.", "kicker": "Decide how to keep the value of a breakthrough.", "fullText": "Attention Is All You Need was published on June 12, 2017, by eight Google researchers. It introduced the Transformer and has been cited more than 250,000 times. All eight authors later left Google to join other companies or found startups.\n\nChatGPT reached about 100 million monthly users in January 2023, two months after launch. Ideas published openly travel with the people who had them, and the company that ships to users captures the value.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who captured the first wave of users from the Transformer idea?", "left": {"name": "Google", "note": "Invented it in 2017"}, "right": {"name": "OpenAI", "note": "Shipped ChatGPT in late 2022"}, "correctIndex": 1, "explanation": "The inventor published. The shipper reached 100 million users in two months."}, "numbers": {"kind": "numberSense", "prompt": "ChatGPT reached about 100 million monthly users how many months after launch?", "min": 0, "max": 12, "value": 2, "unit": "months", "explanation": "About two months. Shipping fast can outrun years of invention."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to join this research group.", "prompt": "What should you ask its lead?", "options": ["Whether its research ships into products", "How many papers it publishes each year", "How large its office space is"], "correctIndex": 0, "consequences": ["Research that ships keeps people and captures value.", "Papers spread ideas others can ship.", "Space says nothing about where the work goes."], "explanation": "Ask where the work ends up. Groups whose ideas never ship tend to lose their people."}, "proReasoning": "Ask how research reaches users. It predicts whether the team will stay together.", "commonMistake": "Judging a lab only by its paper count.", "mentalModel": "Ask where the work ships."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in this company and see its researchers leaving for startups.", "prompt": "How do you read it?", "options": ["As good, since fewer staff cost less", "As a warning about who captures value", "As fine, since the papers stay behind"], "correctIndex": 1, "consequences": ["Saving salaries is small next to losing the next product.", "All eight Transformer authors left, and value went elsewhere.", "Papers are public; the know-how leaves."], "explanation": "Where talent goes, power tends to follow. Departures can signal value walking out."}, "proReasoning": "Investors treat a research exodus as a signal about future products, not just costs.", "commonMistake": "Counting departures as savings.", "mentalModel": "An exodus is a signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the group's lead and must decide what to do with the method.", "prompt": "What's your best move?", "options": ["Publish it and hope the team stays", "Keep it secret in the lab for now", "Put it in a product users can try"], "correctIndex": 2, "consequences": ["Publishing hands the idea to everyone, people included.", "A shelved idea is how inventors end up leaving.", "Shipping captures value and gives the team a reason to stay."], "explanation": "Power goes to whoever turns ideas into products and keeps the people."}, "proReasoning": "Leaders who ship keep both the value and the people. Holding back loses both.", "commonMistake": "Treating publication or secrecy as a strategy.", "mentalModel": "Ship it and keep the team."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a smaller company can beat the one that invented the idea.", "prompt": "What's the answer?", "options": ["It shipped to users first", "It had more patents", "It had bigger offices"], "correctIndex": 0, "consequences": ["ChatGPT reached 100 million users in two months.", "The Transformer was published openly for anyone to use.", "Offices do not win users."], "explanation": "Being first to users can matter more than being first to the idea."}, "proReasoning": "Ask who reached users first. It often explains who won.", "commonMistake": "Assuming the inventor keeps the lead.", "mentalModel": "First to users often wins."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$c2822161-c5c5-565e-84e9-bd1cbba65c94$ml$::uuid, $ml$ai$ml$, 10, 1, $ml${"id": "ai-d10-c1", "title": "Far past twenty to one", "lessonTitle": "Twenty tokens per parameter", "slot": 1, "type": "apply", "brief": {"headline": "Google trained its Gemma 3 27B model on 14 trillion tokens, about 520 tokens per parameter. Chinchilla's compute-optimal ratio is about 20. Google wanted a model that runs on a single GPU.", "kicker": "Apply day 10: why train a small model on so much data?", "fullText": "Gemma 3 came out in March 2025 in four sizes. Its model card lists the training data: 2 trillion tokens for the 1 billion parameter model, 4 trillion for 4B, 12 trillion for 12B and 14 trillion for 27B. Sundar Pichai said the 27B model runs on just one H100 GPU.\n\nChinchilla found that for a fixed training budget, about 20 tokens per parameter gives the best model. Gemma 3 went far past that, to keep the model small enough to run cheaply.\n\nThe day 10 idea still holds: data matters as much as size. A smaller, well-trained model makes a cheaper product possible.", "sources": [{"url": "https://ai.google.dev/gemma/docs/core/model_card_3", "label": "Google, Gemma 3 model card, 2025"}, {"url": "https://www.tipranks.com/news/google-googl-launches-its-gemma-3-ai-model-that-can-run-on-one-chip", "label": "TipRanks, Google launches Gemma 3 that can run on one chip, Mar 2025"}, {"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Gemma 3 27B used about 520 tokens per parameter, far above Chinchilla's 20. What was Google aiming for?", "options": ["A small model that is cheap to run", "The biggest model it could train", "Using as little data as possible"], "correctIndex": 0, "explanation": "More data made a small model stronger. Small enough to run on one GPU means cheaper answers."}, "numbers": {"kind": "numberSense", "prompt": "Gemma 3's 1B model trained on 2 trillion tokens. How many thousand tokens per parameter is that?", "min": 0, "max": 5, "value": 2, "unit": "K", "explanation": "About 2,000 tokens per parameter, a hundred times the Chinchilla ratio."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on a model team. They ask why anyone trains a small model far past 20 tokens per parameter.", "prompt": "What's your answer?", "options": ["Chinchilla said more data is always optimal", "Small models cannot use less data", "It makes the model cheaper to run at scale"], "correctIndex": 2, "consequences": ["Chinchilla found 20 to 1 optimal for a fixed training budget.", "They can; the choice is about running costs.", "A small, strong model saves on every answer it serves."], "explanation": "Chinchilla optimizes the training budget. Builders who serve a model a lot may push data further."}, "proReasoning": "Quote the 20 to 1 ratio, then say when you would break it. That shows you know the trade.", "commonMistake": "Treating 20 to 1 as a law rather than a training-budget rule.", "mentalModel": "Know the rule, and when to break it."}, "invest": {"call": {"kind": "theCall", "situation": "A company says its small model, trained on 100 times the Chinchilla ratio, runs on one GPU.", "prompt": "Why might that matter for its margins?", "options": ["Each answer is cheaper to serve", "It needed no training compute at all", "It removes the need for any data"], "correctIndex": 0, "consequences": ["Smaller models cost less to run, answer after answer.", "Training on that much data takes plenty of compute.", "It used far more data, not less."], "explanation": "Smaller, well-trained models make cheaper products possible. That shows up in serving costs."}, "proReasoning": "Investors look at model size as a running cost. A small model that performs well can widen margins.", "commonMistake": "Assuming bigger models are always the better business.", "mentalModel": "Small and well trained can mean margin."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product needs a model that runs on customers' laptops.", "prompt": "What kind of model do you want?", "options": ["A small model trained on little data", "A small model trained on lots of data", "The largest model you can afford"], "correctIndex": 1, "consequences": ["Little data makes a small model weak.", "That is the Gemma 3 recipe: small enough to run, strong from data.", "A huge model will not fit on a laptop."], "explanation": "Data matters as much as size. A small model needs plenty of it to be good."}, "proReasoning": "Founders pick the size the product can run, then make it strong with data.", "commonMistake": "Picking size first and data as an afterthought.", "mentalModel": "Fix the size, then add data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a model small enough for one chip can still be good.", "prompt": "What's the answer?", "options": ["It looks up answers from a bigger model", "Its chip is a hundred times faster", "It was trained on huge amounts of data"], "correctIndex": 2, "consequences": ["It runs on its own once trained.", "It runs on a standard H100, not a special chip.", "Gemma 3 27B saw 14 trillion tokens in training."], "explanation": "Size is not everything. A smaller model trained on more data can do well."}, "proReasoning": "A model is size plus training data. Lots of data can make up for a small size.", "commonMistake": "Judging a model by parameter count alone.", "mentalModel": "Size plus data, not size alone."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e17c9a48-e467-5f9f-a2e2-c8d918d69562$ml$::uuid, $ml$ai$ml$, 10, 2, $ml${"id": "ai-d10-c2", "title": "Same budget, better model", "lessonTitle": "Twenty tokens per parameter", "slot": 2, "type": "connect", "brief": {"headline": "Chinchilla used the same compute as Gopher, a model four times its size, and beat it. When a training run costs tens of millions, how you split the budget matters as much as its size.", "kicker": "Connect day 8 and day 10: how you spend the training budget counts.", "fullText": "On day 8 you saw training costs climb from about $900 for the 2017 Transformer to an estimated $78 million for GPT-4. On day 10 you met DeepMind's Chinchilla: 70 billion parameters trained on 1.4 trillion tokens, about 20 tokens per parameter.\n\nChinchilla used the same compute as the 280-billion-parameter Gopher and outperformed it, along with GPT-3, which had 175 billion parameters trained on 300 billion tokens.\n\nWhen compute costs tens of millions, the split between model size and data decides what you get for the money.", "sources": [{"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://ar5iv.labs.arxiv.org/html/2005.14165", "label": "Brown et al., Language models are few-shot learners, 2020"}]}, "evidence": {"kind": "faceOff", "prompt": "Same compute budget. Which model performed better?", "left": {"name": "Gopher", "note": "280 billion parameters"}, "right": {"name": "Chinchilla", "note": "70 billion parameters, 1.4 trillion tokens"}, "correctIndex": 1, "explanation": "Chinchilla spent the same compute on a smaller model and far more data, and won."}, "numbers": {"kind": "numberSense", "prompt": "GPT-3 had 175 billion parameters and trained on 300 billion tokens. About how many tokens per parameter?", "min": 0, "max": 10, "value": 1.7, "unit": "tokens", "explanation": "About 1.7, far below Chinchilla's 20. GPT-3 was big for its data."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how you'd spend a fixed training budget.", "prompt": "What's your answer?", "options": ["Balance size and data, about 20 to 1", "Make the model as big as the budget allows", "Use the least data possible to save money"], "correctIndex": 0, "consequences": ["That is the Chinchilla finding, and it beat bigger models.", "Gopher did that and lost to a smaller model.", "Starving the model of data wastes the compute."], "explanation": "For compute-optimal training, model size and data should grow together."}, "proReasoning": "Quote the ratio and the result: 20 tokens per parameter, and a model four times smaller won.", "commonMistake": "Equating a bigger model with a better use of money.", "mentalModel": "Size and data grow together."}, "invest": {"call": {"kind": "theCall", "situation": "A lab brags that its new model is the biggest ever built.", "prompt": "What do you ask?", "options": ["Nothing, since bigger means better", "How much data it was trained on", "How many people worked on it"], "correctIndex": 1, "consequences": ["Gopher was bigger than Chinchilla and lost.", "Without enough data, size can waste a costly budget.", "Headcount says little about the training split."], "explanation": "Data is a cost driver. Size without data is money spent badly."}, "proReasoning": "Investors ask about data, not just parameters. It tells them if the budget was well spent.", "commonMistake": "Reading model size as a measure of quality.", "mentalModel": "Ask about data, not just size."}, "build_startup": {"call": {"kind": "theCall", "situation": "You have a fixed compute budget to train a model for your field.", "prompt": "How do you spend it?", "options": ["Largest model on whatever data you have", "Two giant models trained on little data", "Smaller model, more training data"], "correctIndex": 2, "consequences": ["That repeats the mistake Chinchilla corrected.", "Little data starves both models.", "Same budget, better model, as Chinchilla showed."], "explanation": "For a fixed budget, a smaller model trained on more data can win."}, "proReasoning": "Founders get more from a fixed budget by balancing size and data. Smaller is also cheaper to serve.", "commonMistake": "Spending the budget on size alone.", "mentalModel": "Balance the budget."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a smaller AI beat one four times its size.", "prompt": "What's the answer?", "options": ["It learned from far more data", "It ran on a faster computer", "The bigger model was broken"], "correctIndex": 0, "consequences": ["Chinchilla trained on 1.4 trillion tokens.", "Both used the same compute.", "Gopher worked; it just had too little data for its size."], "explanation": "Same compute, better split. Data mattered as much as size."}, "proReasoning": "Bigger is not always better. How you train matters as much as how big you build.", "commonMistake": "Assuming size decides the winner.", "mentalModel": "Training beats size alone."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f5e216ee-0d08-5d65-b385-9efa7098a122$ml$::uuid, $ml$ai$ml$, 10, 3, $ml${"id": "ai-d10-c3", "title": "Two trillion tokens to spend", "lessonTitle": "Twenty tokens per parameter", "slot": 3, "type": "decide", "brief": {"headline": "You run a lab with about 2 trillion tokens of quality text for a new model. Chinchilla's rule of thumb is about 20 training tokens for each parameter.", "kicker": "Decide what size of model your data can support.", "fullText": "DeepMind's Chinchilla found that for compute-optimal training, model size and training tokens should be scaled equally. Chinchilla had 70 billion parameters trained on 1.4 trillion tokens, about 20 tokens per parameter, and beat the 280-billion-parameter Gopher on the same compute.\n\nGPT-3, in 2020, had 175 billion parameters trained on 300 billion tokens. If models need about 20 tokens per parameter, data supply matters as much as chips.", "sources": [{"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://ar5iv.labs.arxiv.org/html/2005.14165", "label": "Brown et al., Language models are few-shot learners, 2020"}]}, "evidence": {"kind": "buildChain", "prompt": "Work out the compute-optimal size for your data.", "steps": ["Start with 2 trillion tokens of data", "Use about 20 tokens per parameter", "Divide 2 trillion by 20", "Aim for about 100 billion parameters"], "explanation": "The ratio turns your data into a size. Bigger than that, and the data runs thin."}, "numbers": {"kind": "numberSense", "prompt": "With 2 trillion tokens at about 20 per parameter, how many billion parameters?", "min": 0, "max": 300, "value": 100, "unit": "B", "explanation": "About 100 billion. A 400 billion model would get only 5 tokens per parameter."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team lead proposes a 400 billion parameter model on the 2 trillion tokens.", "prompt": "What do you say?", "options": ["Suggest cutting the data down to 1 trillion", "Flag that the data supports about 100 billion", "Agree, since bigger models always win out"], "correctIndex": 1, "consequences": ["Less data makes the imbalance worse.", "At 400 billion, each parameter gets only 5 tokens.", "Gopher was bigger than Chinchilla and lost."], "explanation": "Data and model size have to grow together. The data sets a sensible size."}, "proReasoning": "Back your view with the ratio: 2 trillion over 20 is 100 billion. Numbers win the argument.", "commonMistake": "Going along with size for its own sake.", "mentalModel": "Let the data set the size."}, "invest": {"call": {"kind": "theCall", "situation": "The lab plans to double its model size next year.", "prompt": "What do you ask?", "options": ["Whether the new name is ready", "Nothing, since bigger is safer", "Where twice the data will come from"], "correctIndex": 2, "consequences": ["Names do not train models.", "Size without data wastes compute.", "Doubling size calls for about double the data."], "explanation": "Data is a cost driver. Scaling the model means scaling the data supply too."}, "proReasoning": "Investors ask about the data plan behind a scaling plan. Data can be the bottleneck.", "commonMistake": "Assuming the data will simply appear.", "mentalModel": "Scale the data with the model."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want a stronger model, but you've used all your quality data.", "prompt": "What's your next step?", "options": ["Find more quality data before scaling", "Just add more parameters", "Train longer on the same small set"], "correctIndex": 0, "consequences": ["More data lets a bigger model pay off.", "More size on the same data repeats the Gopher mistake.", "Data matters as much as size, and you are short of it."], "explanation": "Data and size grow together. Without new data, a bigger model is a poor use of compute."}, "proReasoning": "Founders see data as a real constraint. Getting more of it can matter more than buying chips.", "commonMistake": "Scaling the model when the data is the limit.", "mentalModel": "Data first, then size."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI companies keep hunting for more text.", "prompt": "What's the answer?", "options": ["They are building a new search engine", "Bigger models need more data to pay off", "Text is needed to store the models"], "correctIndex": 1, "consequences": ["They need it for training, whatever the product.", "About 20 tokens per parameter, so size needs data.", "Data trains the model; it does not store it."], "explanation": "If models need about 20 tokens per parameter, growing models need growing data."}, "proReasoning": "Model size and data rise together. That is why data has become valuable.", "commonMistake": "Thinking only chips limit AI.", "mentalModel": "More model, more data."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$febc7e02-e3eb-58ba-a935-9d703adc59c2$ml$::uuid, $ml$ai$ml$, 11, 1, $ml${"id": "ai-d11-c1", "title": "A price for every extra page", "lessonTitle": "Why reading more costs more", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, Anthropic raised Claude Sonnet 4's context window to 1 million tokens, five times the old limit. Prompts over 200,000 tokens cost $6 per million input tokens, double the usual $3.", "kicker": "Apply day 11: why long prompts cost more per token.", "fullText": "It was the first time Anthropic varied prices by context length. Up to 200,000 tokens, input cost $3 per million and output $15. Above that, input cost $6 and output $22.50. Google's Gemini 2.5 Pro already used a similar split: $1.25 per million input tokens below 200,000 and $2.50 above.\n\nThe day 11 reason sits inside the Transformer. Attention's work grows with the square of the input length, so doubling the text roughly quadruples it. Long context is a feature, and also a cost someone has to pay.", "sources": [{"url": "https://simonwillison.net/2025/Aug/12/claude-sonnet-4-1m", "label": "Simon Willison, Claude Sonnet 4 1M context, Aug 2025"}, {"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow why long prompts cost more.", "steps": ["A prompt grows from 200,000 to 400,000 tokens", "Attention work roughly quadruples", "Each request needs much more compute", "The provider charges more above 200,000 tokens"], "explanation": "Work that grows with the square of length turns into a higher price per token."}, "numbers": {"kind": "numberSense", "prompt": "A 600,000-token prompt at $6 per million input tokens costs how many dollars?", "min": 0, "max": 10, "value": 3.6, "unit": "dollars", "explanation": "$3.60 for one request. At scale, every long prompt adds up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an AI product role. They ask why long prompts cost more per token.", "prompt": "What's your answer?", "options": ["Attention work grows with the square of length", "Long prompts are stored on servers for longer", "Popular features are simply priced higher"], "correctIndex": 0, "consequences": ["That ties the price to how the model works.", "Storage is not what drives the cost.", "The extra price follows extra compute."], "explanation": "Knowing why long context is expensive explains why teams trim what they send."}, "proReasoning": "Explain prices with the mechanism. Quadratic attention is why the second 200,000 tokens cost more.", "commonMistake": "Treating long-context pricing as a marketing choice.", "mentalModel": "Price follows the mechanism."}, "invest": {"call": {"kind": "theCall", "situation": "A model provider advertises a 1 million token window.", "prompt": "What should you check?", "options": ["Nothing, since bigger windows are free", "How it prices and serves long prompts", "Only the size of the window"], "correctIndex": 1, "consequences": ["Doubling input roughly quadruples attention work.", "Long context is a cost line, and pricing shows who pays it.", "Size is the selling point, not the economics."], "explanation": "Million-token windows sell well, but each doubling of input roughly quadruples attention work."}, "proReasoning": "Investors ask who absorbs the cost of long context. Tiered prices show the provider passing it on.", "commonMistake": "Treating window size as pure upside.", "mentalModel": "Context is a cost line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app sends a whole 400-page manual with every user question.", "prompt": "What do you change?", "options": ["Pay the long-context rate and send it all", "Wait for windows to get even bigger", "Find the relevant pages first, send those"], "correctIndex": 2, "consequences": ["You pay double rates for pages the answer does not need.", "Bigger windows do not make long prompts cheaper.", "Shorter prompts cut attention work and the bill."], "explanation": "Serving long context takes heavy compute. A small team has to be selective."}, "proReasoning": "Founders send models only what each answer needs. It is the cheapest speedup there is.", "commonMistake": "Using the whole window because it is there.", "mentalModel": "Send what the answer needs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Claude charges double for very long prompts.", "prompt": "What's the best explanation?", "options": ["Reading more costs disproportionately more", "Anthropic wants people to read less often", "Long prompts need a human to review them"], "correctIndex": 0, "consequences": ["Doubling the text roughly quadruples attention work.", "The price reflects compute, not a wish.", "No human reads your prompt."], "explanation": "In Transformers, reading more costs disproportionately more, and prices follow."}, "proReasoning": "Some costs grow faster than the thing you measure. Attention is one.", "commonMistake": "Assuming twice the text means twice the work.", "mentalModel": "Twice the text, four times the work."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f7875f8b-d58e-5b7a-9054-4fbc8d73fb42$ml$::uuid, $ml$ai$ml$, 11, 2, $ml${"id": "ai-d11-c2", "title": "The price of parallel", "lessonTitle": "Why reading more costs more", "slot": 2, "type": "connect", "brief": {"headline": "The Transformer dropped recurrence so it could process a sequence in parallel. The trade: its attention work grows with the square of the input length.", "kicker": "Connect day 7 and day 11: parallel speed came with a quadratic bill.", "fullText": "On day 7 you saw why the Transformer won: RNNs read one step at a time, while attention needs only a constant number of sequential steps, so it runs in parallel. On day 11 you saw the price. Table 1 of the 2017 paper lists self-attention's per-layer work as n squared times d, where n is the input length, against n times d squared for recurrent layers.\n\nFor short inputs the trade is a bargain. As context windows grow toward the 1 million tokens Gemini 1.5 Pro previewed in 2024, the square term takes over.", "sources": [{"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://developers.googleblog.com/2024/02/gemini-15-available-for-private-preview-in-google-ai-studio.html", "label": "Google for Developers, Gemini 1.5 private preview, Feb 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Self-attention needs a constant number of sequential steps.", "RNNs read a sequence one step at a time.", "Attention work grows in a straight line with input length."], "fakeIndex": 2, "explanation": "Attention work grows with the square of the input length. That is the price of running in parallel."}, "numbers": {"kind": "numberSense", "prompt": "An input grows 10 times longer. About how many times more attention work?", "min": 0, "max": 300, "value": 100, "unit": "x", "explanation": "Ten squared is 100. Long inputs get expensive fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked what the Transformer gave up to run in parallel.", "prompt": "What's the answer?", "options": ["Its ability to run well on GPUs at all", "Work that grows with the square of input", "Accuracy on short, simple sentences"], "correctIndex": 1, "consequences": ["Running in parallel is what suits GPUs.", "That is the trade in Table 1 of the paper.", "Transformers did well on short text too."], "explanation": "Parallel processing came at the cost of quadratic attention. Both facts explain modern AI costs."}, "proReasoning": "Name both sides of a design trade. Interviewers trust people who know the cost of a win.", "commonMistake": "Describing the Transformer as all upside.", "mentalModel": "Every design win has a price."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims a new design that reads long inputs at much lower cost than attention.", "prompt": "How do you treat the claim?", "options": ["Ignore it, since the Transformer can't change", "Assume it is worse, since it is new", "Watch it, since it targets attention's big cost"], "correctIndex": 2, "consequences": ["A 2017 paper already changed which models won once.", "New designs have won before.", "A design that cuts that cost could change what AI costs to run."], "explanation": "Watch for architecture shifts. Quadratic attention is the obvious target."}, "proReasoning": "Investors know where today's design is weakest and watch for fixes there.", "commonMistake": "Assuming the current design is final.", "mentalModel": "Watch the weak spot."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product mostly handles short messages, but some users paste huge files.", "prompt": "How do you design for both?", "options": ["Keep short inputs cheap; handle big files apart", "Treat every input like a huge file upload", "Send every file to the model in full, always"], "correctIndex": 0, "consequences": ["Short inputs stay cheap, and big files get special handling.", "You would pay long-input costs on every short message.", "Full files make the square term dominate your bill."], "explanation": "Attention is a bargain for short inputs and costly for long ones. Design around both."}, "proReasoning": "Founders treat long inputs as a separate case with its own cost.", "commonMistake": "Designing every request for the worst case.", "mentalModel": "Short is cheap; plan for long."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if Transformers are so fast, why do long documents slow them down?", "prompt": "What's the answer?", "options": ["Long documents use longer words on average", "Their work grows with the square of length", "They read one word at a time, in order"], "correctIndex": 1, "consequences": ["Word length is not the issue; token count is.", "Double the text and attention work roughly quadruples.", "That describes RNNs, not Transformers."], "explanation": "Transformers run in parallel, but their attention work grows with the square of input length."}, "proReasoning": "Fast for short inputs, costly for long ones: both are true of the same design.", "commonMistake": "Thinking a fast design is fast for every input.", "mentalModel": "Fast in parallel, costly at length."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$7df1eafd-c9c4-5b5a-aeca-425527410264$ml$::uuid, $ml$ai$ml$, 11, 3, $ml${"id": "ai-d11-c3", "title": "The chat that kept growing", "lessonTitle": "Why reading more costs more", "slot": 3, "type": "decide", "brief": {"headline": "You run a support chatbot that sends a customer's whole chat history with every new message. Long conversations have made some requests slow and costly.", "kicker": "Decide how to cut the cost of long conversations.", "fullText": "Table 1 of the 2017 Transformer paper lists self-attention's per-layer work as n squared times d, where n is the input length. Double the text a Transformer reads, and its attention work roughly quadruples.\n\nIn February 2024, Google previewed Gemini 1.5 Pro with a context window of up to 1 million tokens, about 700,000 words. Big windows are a feature. Filling them on every request is a cost decision.", "sources": [{"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://developers.googleblog.com/2024/02/gemini-15-available-for-private-preview-in-google-ai-studio.html", "label": "Google for Developers, Gemini 1.5 private preview, Feb 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each change cut the attention work per request?", "buckets": ["Cuts the work", "Doesn't cut it"], "items": [{"text": "Send only the recent, relevant messages", "bucket": 0}, {"text": "Summarize old messages into a short note", "bucket": 0}, {"text": "Drop pasted logs the question doesn't need", "bucket": 0}, {"text": "Switch to a model with a bigger window", "bucket": 1}, {"text": "Send the full history twice for safety", "bucket": 1}], "explanation": "Only shorter inputs cut attention work. A bigger window lets you send more, which costs more."}, "numbers": {"kind": "numberSense", "prompt": "A conversation grows from 5,000 to 20,000 tokens. About how many times more attention work?", "min": 0, "max": 50, "value": 16, "unit": "x", "explanation": "Four times the length, so about 16 times the work. Long chats get costly fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join the team as an engineer. Your first task is to cut costs without hurting answers.", "prompt": "What do you try first?", "options": ["Buy a model with a bigger context window", "Send the full history only on weekends", "Trim each request to the relevant messages"], "correctIndex": 2, "consequences": ["A bigger window does not make long inputs cheaper.", "Cost would still spike on weekends.", "Shorter inputs cut attention work, and good answers rarely need it all."], "explanation": "Attention work grows with the square of length. Trimming input is the biggest lever."}, "proReasoning": "Engineers who know why long context is expensive go straight to trimming input.", "commonMistake": "Reaching for a bigger model when the problem is input size.", "mentalModel": "Trim input first."}, "invest": {"call": {"kind": "theCall", "situation": "The chatbot's maker says usage is up, but cost per chat is rising faster.", "prompt": "What do you ask?", "options": ["How much context each request sends", "Whether users like the chatbot", "How many servers it rents"], "correctIndex": 0, "consequences": ["Growing histories square the attention work.", "Liking it does not explain the cost curve.", "Server count follows the input size."], "explanation": "Context is a cost line. Rising cost per chat often means growing inputs."}, "proReasoning": "Investors trace rising unit costs to their cause. Here, it is how much text each request carries.", "commonMistake": "Blaming usage when the cost is in the input.", "mentalModel": "Find the cost driver."}, "build_startup": {"call": {"kind": "theCall", "situation": "Customers want the bot to remember months of history.", "prompt": "How do you deliver that?", "options": ["Refuse to keep any customer history at all", "Store it, send only what each answer needs", "Send all of it along with every message"], "correctIndex": 1, "consequences": ["You lose a feature customers want.", "Customers get memory, and requests stay short.", "Months of history would make every message slow and costly."], "explanation": "Keep history in storage and retrieve what matters. Long context is a cost decision."}, "proReasoning": "Founders separate what the product remembers from what the model reads. That keeps costs sane.", "commonMistake": "Equating memory with sending everything every time.", "mentalModel": "Remember everything, send little."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would limit how much text its chatbot reads at once.", "prompt": "What's the answer?", "options": ["Chatbots get bored with very long chats", "Storing long text is against the law", "Reading more costs disproportionately more"], "correctIndex": 2, "consequences": ["Chatbots do not get bored; the cost rises.", "Storage is legal; reading it all is the cost.", "Double the text, about four times the attention work."], "explanation": "In Transformers, reading more costs disproportionately more. Limits keep costs in check."}, "proReasoning": "Limits on input are usually about cost, not capability.", "commonMistake": "Assuming limits mean the AI cannot cope.", "mentalModel": "Limits are often about cost."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$27b2a76d-5511-538c-8dfb-87bdcb975f14$ml$::uuid, $ml$ai$ml$, 12, 1, $ml${"id": "ai-d12-c1", "title": "References that did not exist", "lessonTitle": "Six cases that never existed", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, Deloitte agreed to refund part of an A$440,000 contract with Australia's government. Its report had cited sources that did not exist and a quote a court judgment does not contain.", "kicker": "Apply day 12: a citation that looks right still needs checking.", "fullText": "The Department of Employment and Workplace Relations paid Deloitte to review the Targeted Compliance Framework, a system for penalizing welfare recipients who miss obligations. After the report came out in July 2025, University of Sydney researcher Christopher Rudge spotted more than a dozen bogus references, including reports that did not exist, and a quote attributed to a judge that the cited judgment does not contain.\n\nDeloitte agreed to refund the final instalment. A corrected report removed the bogus references and disclosed the use of a generative AI tool, Azure OpenAI GPT-4o. A source told the Australian Financial Review that Deloitte's internal review blamed human error rather than AI misuse. The department said the substance and recommendations were unchanged.\n\nFluent is not the same as true. Anything high-stakes needs checking against a real source.", "sources": [{"url": "https://www.theregister.com/2025/10/06/deloitte_ai_report_australia/", "label": "The Register, Deloitte refunds Australian government over AI errors, Oct 2025"}, {"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Deloitte report. Tap it.", "statements": ["A researcher spotted the bogus references after it was published.", "The corrected report disclosed use of Azure OpenAI GPT-4o.", "The department withdrew all of the report's recommendations."], "fakeIndex": 2, "explanation": "The department said the recommendations were unchanged. The bogus references were removed."}, "numbers": {"kind": "numberSense", "prompt": "The contract was worth how many thousand Australian dollars?", "min": 0, "max": 1000, "value": 440, "unit": "K", "explanation": "A$440,000. A citation check would have cost far less than the refund and the headlines."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're an analyst at a consulting firm that uses AI to help draft reports.", "prompt": "Which habit protects you most?", "options": ["Remove all citations from reports", "Open every cited source before it ships", "Trust citations that look well formatted"], "correctIndex": 1, "consequences": ["Clients need sources; they need real ones.", "A bogus reference cannot survive someone opening it.", "The bogus references looked like real ones."], "explanation": "Fluent output still needs a source check. Opening the source is the check."}, "proReasoning": "Say where you would require human checks on AI output, and why. Citations are the obvious place.", "commonMistake": "Trusting a reference because it looks professional.", "mentalModel": "Open the source."}, "invest": {"call": {"kind": "theCall", "situation": "A consulting firm tells investors AI will sharply cut the cost of writing reports.", "prompt": "What do you ask?", "options": ["Whether the savings all go to profit", "Nothing, since clients rarely check", "How it checks AI output before delivery"], "correctIndex": 2, "consequences": ["Savings mean little if trust failures erase them.", "A researcher checked, and it made national news.", "Without checks, savings can turn into refunds."], "explanation": "Watch for trust failures. Check how AI work is verified before trusting the savings."}, "proReasoning": "Investors weigh AI savings against the cost of a public error. Verification is part of the business.", "commonMistake": "Counting AI savings without counting the risk.", "mentalModel": "Savings need verification."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build a tool for consultants who draft reports with AI.", "prompt": "Which product meets a real gap?", "options": ["A tool that checks citations exist and match", "A tool that writes citations even faster", "A tool that hides which text used AI"], "correctIndex": 0, "consequences": ["Checking is slow and manual today, and errors are costly.", "Faster citations do not fix invented ones.", "Hiding AI use makes the trust problem worse."], "explanation": "Ask professionals how they verify AI output. If it is slow and manual, that gap is worth testing."}, "proReasoning": "Founders build for the checking problem, not just the writing problem. That is where the pain is.", "commonMistake": "Adding speed to a process whose problem is accuracy.", "mentalModel": "Solve the checking problem."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a big firm's report could cite sources that don't exist.", "prompt": "What's the best explanation?", "options": ["The government changed its court records", "AI tools can invent sources that look real", "The sources were deleted from the internet"], "correctIndex": 1, "consequences": ["The judgment was real; the quote was not in it.", "Confident, well-formatted errors need a check against a real source.", "The reports cited never existed in the first place."], "explanation": "Models can produce citations that look real but are invented. Someone has to check."}, "proReasoning": "Fluent is not the same as true. A real-looking citation is still a claim to check.", "commonMistake": "Thinking polished output must be accurate.", "mentalModel": "Fluent is not true."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$da9c3cdf-a458-5dcd-a665-3d38b848ae7f$ml$::uuid, $ml$ai$ml$, 12, 2, $ml${"id": "ai-d12-c2", "title": "Fast to users, fast to court", "lessonTitle": "Six cases that never existed", "slot": 2, "type": "connect", "brief": {"headline": "ChatGPT reached about 100 million monthly users in January 2023, two months after launch. That June, a judge fined two New York lawyers over a brief citing six cases ChatGPT had made up.", "kicker": "Connect day 9 and day 12: a fast spread carries the flaws with it.", "fullText": "On day 9 you saw why shippers win: ChatGPT reached about 100 million monthly users two months after launch, while the lab that invented the Transformer watched. On day 12 you met two of those users. In Mata v. Avianca, attorneys Steven Schwartz and Peter LoDuca filed a brief citing six fictitious court opinions generated with ChatGPT.\n\nOn June 22, 2023, Judge P. Kevin Castel fined them and their firm $5,000, finding they abandoned their responsibilities and kept defending the fake cases after the court questioned them.\n\nDistribution puts a tool in the hands of people who may not know its limits. The faster a product spreads, the faster its failure modes travel.", "sources": [{"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}, {"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the events in order.", "steps": ["Google researchers introduce the Transformer", "ChatGPT launches and spreads fast", "It reaches about 100 million users", "Lawyers file a brief with invented cases", "A judge fines them $5,000"], "explanation": "The faster a tool reaches users, the sooner its failures show up in their work."}, "numbers": {"kind": "numberSense", "prompt": "The judge fined the lawyers and their firm how many thousand dollars?", "min": 0, "max": 20, "value": 5, "unit": "K", "explanation": "$5,000. The fine was small; the national headlines were not."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a law firm's tech team as AI tools roll out to every lawyer.", "prompt": "What do you push for first?", "options": ["A ban on all AI tools for good", "Free use with no rules at all", "Training on how to check AI output"], "correctIndex": 2, "consequences": ["A ban gives up real gains, and people use tools anyway.", "That is how a brief with six fake cases gets filed.", "Users who know the limits catch invented cases."], "explanation": "A tool that spreads fast needs users who know where it fails."}, "proReasoning": "Have a view on where AI checks belong. Training users is the first line of defense.", "commonMistake": "Choosing between banning AI and ignoring its flaws.", "mentalModel": "Spread the checks with the tool."}, "invest": {"call": {"kind": "theCall", "situation": "An AI product grows to 100 million users in a few months.", "prompt": "What else do you want to know?", "options": ["How it handles errors at that scale", "Nothing, since growth proves reliability", "Only how fast it will keep growing"], "correctIndex": 0, "consequences": ["At scale, rare errors become national news.", "ChatGPT grew fast and still invented court cases.", "Growth with trust failures can stall."], "explanation": "Watch for trust failures. Growth spreads the flaws as fast as the features."}, "proReasoning": "Investors pair growth with reliability. A trust failure at scale can undo the adoption story.", "commonMistake": "Reading fast growth as proof of quality.", "mentalModel": "Growth spreads flaws too."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI writing tool is spreading fast among professionals.", "prompt": "What's the priority?", "options": ["Add a small disclaimer, nothing else", "Build checks in before it spreads further", "Grow first and fix errors later"], "correctIndex": 1, "consequences": ["A disclaimer did not stop the lawyers.", "Checks protect users and your reputation as you scale.", "Later can mean after a headline like Avianca."], "explanation": "The faster a product spreads, the more its errors matter. Build verification in early."}, "proReasoning": "Founders treat verification as a feature, especially for professional users.", "commonMistake": "Treating errors as a problem for later.", "mentalModel": "Build the check in early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why experienced lawyers trusted a chatbot's cases.", "prompt": "What's the best explanation?", "options": ["The chatbot was certified for legal work", "The court told them to use it", "The answers looked fluent and confident"], "correctIndex": 2, "consequences": ["No such certification existed.", "The court questioned the cases; it did not suggest the tool.", "Well-formatted errors are easy to mistake for real cases."], "explanation": "Fluent output feels trustworthy. That is exactly why it needs checking."}, "proReasoning": "Confidence and accuracy are different things. A chatbot can have one without the other.", "commonMistake": "Taking a confident tone as evidence.", "mentalModel": "Confidence is not evidence."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e01874d2-81c4-5f14-baa5-4f70f1c11506$ml$::uuid, $ml$ai$ml$, 12, 3, $ml${"id": "ai-d12-c3", "title": "The judge asks a question", "lessonTitle": "Six cases that never existed", "slot": 3, "type": "decide", "brief": {"headline": "You run a small law firm. A judge has questioned citations in a brief your associate filed, and the associate admits using a chatbot to find them.", "kicker": "Decide what your firm does next.", "fullText": "In Mata v. Avianca, attorneys filed a brief citing six fictitious court opinions generated with ChatGPT. The model produced citations that looked real but were invented, which is called a hallucination.\n\nOn June 22, 2023, Judge P. Kevin Castel fined the lawyers and their firm $5,000. He found they abandoned their responsibilities and kept defending the fake cases after the court questioned them. What they did after the question mattered as much as the error.", "sources": [{"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "In Mata v. Avianca, what made things worse for the lawyers?", "options": ["They kept defending the fake cases", "They used a computer to write the brief", "They cited too many real cases"], "correctIndex": 0, "explanation": "The judge found they kept defending the fake cases after the court questioned them."}, "numbers": {"kind": "numberSense", "prompt": "If checking one citation takes 10 minutes, how many hours does a brief with 30 citations take?", "min": 0, "max": 12, "value": 5, "unit": "hours", "explanation": "Five hours. Slow, but far cheaper than a sanction and a headline."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the associate who filed the brief. The judge asks about your citations.", "prompt": "What do you do?", "options": ["Check each one now and correct the record", "Defend them until proven fake", "Blame the chatbot and say nothing else"], "correctIndex": 0, "consequences": ["Owning the error early is what the Avianca lawyers failed to do.", "Defending fake cases is what made Avianca worse.", "Lawyers answer for what they file, whatever tool they used."], "explanation": "The error was bad. Defending it after being questioned was worse."}, "proReasoning": "When AI output is questioned, verify fast and correct the record. Credibility is the asset at stake.", "commonMistake": "Doubling down to save face.", "mentalModel": "Verify, then correct."}, "invest": {"call": {"kind": "theCall", "situation": "You're weighing an investment in a legal AI tool after cases like this one.", "prompt": "What matters most?", "options": ["How many lawyers have signed up so far", "How it ties each citation to a real source", "How fluent and polished its writing sounds"], "correctIndex": 1, "consequences": ["Users leave fast after a trust failure.", "Verifiable citations address the exact failure.", "Fluent writing is what fooled the lawyers."], "explanation": "Check how an AI product handles verification before trusting its adoption story."}, "proReasoning": "Investors in professional AI tools ask about verification first. Trust is the product.", "commonMistake": "Being impressed by fluency.", "mentalModel": "Trust is the product."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the firm and must set a new rule for AI-assisted filings.", "prompt": "Which rule works best?", "options": ["Ban AI and stop checking citations", "Allow AI if the brief reads well", "A named lawyer verifies every cited case"], "correctIndex": 2, "consequences": ["Human-found citations need checking too.", "Reading well is how the fake cases passed.", "Every citation gets a real check and an owner."], "explanation": "Fluent output still needs a source check, and someone has to own it."}, "proReasoning": "Good rules name who checks what. A rule without an owner is a wish.", "commonMistake": "Writing a policy no one is responsible for.", "mentalModel": "Every check needs an owner."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if the AI made the mistake, why were the lawyers fined?", "prompt": "What's the answer?", "options": ["Lawyers answer for what they file", "The lawyers wrote the chatbot", "The AI company paid the fine"], "correctIndex": 0, "consequences": ["The judge found they abandoned their responsibilities.", "They used the chatbot; they did not build it.", "The fine went to the lawyers and their firm."], "explanation": "A tool can make the error. The professional who signs the work owns it."}, "proReasoning": "Responsibility follows the signature, not the software.", "commonMistake": "Blaming the tool for what a person signed.", "mentalModel": "The signer owns it."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[])
